  ["22|Travel to The Sepulcher in Silverpine Forest and speak with Trevan Rol about the missing Earthen Ring travelers."] = "22|前往銀松森林的瑟伯切爾，和崔凡‧羅爾談談失蹤的陶土議會旅人。",
