  ["Add to wishlist"] = "加入願望清單",
  ["Add your own buffs below (e.g. Demon Skin) with the time in seconds. When the buff has less time left, or has run out, a small popup says so; click its icon to cast the buff again (not in combat - there it only shows). It goes away by itself once you renew the buff. Drag the popup to move it."] = "在下面加入你自己的增益效果（例如惡魔皮膚）和秒數。當增益效果剩餘時間少於設定值或已消失時，會跳出小提示視窗；點它的圖示可再施放一次（戰鬥中不行——戰鬥中只顯示）。你重新施放後它會自己消失。拖曳提示視窗可移動它。",
  ["Addon tabs"] = "插件分頁",
  ["Adds a button to every chat window to copy its text."] = "在每個聊天視窗加上複製文字的按鈕。",
  ["Advanced campsite healing/poultice utility; exact beta behavior is still being documented."] = "進階的營地治療／藥膏設施；測試版的確切運作方式仍在整理中。",
  ["Advice From Stormwind"] = "來自暴風城的建議",
  ["Aeonas"] = "艾奧納斯",
  ["After Archaedas, speak with the stone watcher and activate the Discs of Norgannon. The follow-up depends on your faction."] = "打完阿札達斯後，和石頭看守者談話並啟動諾甘農圓盤。後續任務依你的陣營而不同。",
  ["After casting your Healing Wave or Lesser Healing Wave spell, gives you a 25% chance to gain Mana equal to 35% of the base cost of the spell. (Proc chance: 25%, 1s cooldown)"] = "施放治療波或次級治療波後，有25%的機率獲得相當於該法術基礎消耗35%的法力。（觸發機率：25%，冷卻1秒）",
  ["Afterwards Alba Fairmoon at the exit asks you to use the detonator (part 2)."] = "之後出口處的艾芭‧皎月會請你使用引爆器（第 2 部分）。",
  ["Agamaggan's Blood"] = "阿迦瑪甘之血",
