  ["All zones of the continent at once, a little smaller, without the routes of walking quest givers. Needs \"Quest icons\"."] = "一次顯示大陸上所有區域，圖示稍小，不顯示會走動的任務給予者路線。需要開啟「任務圖示」。",
  ["All-in-one WoW Forever companion: dungeons, quests, loot, item sets and reputation rewards, Library Books, professions, talent planning, hunter pets and quality of life helpers."] = "WoW Forever 全能助手：地城、任務、掉落、套裝與聲望獎勵、圖書館書籍、專業技能、天賦規劃、獵人寵物和生活便利小工具。",
  ["Alliance territory"] = "聯盟領地",
  ["Allow duels from"] = "允許誰的決鬥",
  ["Allows 15% of your Mana regeneration to continue while casting."] = "使你在施法時仍保有15%的法力恢復速度。",
  ["Allows cooking and up to 10 additional camp features."] = "可以烹飪，並可再放最多 10 個營地設施。",
  ["Allows cooking and up to 3 additional camp features; nearby players gain camp benefits after resting/crafting for 1 minute."] = "可以烹飪，並可再放最多 3 個營地設施；附近的玩家休息／製作 1 分鐘後可獲得營地效果。",
  ["Allows cooking and up to 5 additional camp features."] = "可以烹飪，並可再放最多 5 個營地設施。",
  ["Alpha"] = "透明度",
  ["Alphonse Dumas"] = "阿方斯·杜馬斯",
  ["Also hides \"You've collected this appearance, but not from this item\". Hover the item again after switching."] = "也會隱藏「你已收藏這個外觀，但不是來自這個物品」。切換後請把滑鼠重新移到物品上。",
  ["Also on the continent map"] = "大陸地圖上也顯示",
  ["Also shows looted money."] = "也顯示拾取的金錢。",
  ["Also the button of the minimap button collector."] = "也包括小地圖按鈕收集器的按鈕。",
  ["Also the items on your own junk list: Alt+right-click an item in your bags to put it on the list or take it off. Hold Shift at the merchant to skip."] = "也包括你自己垃圾清單上的物品：在背包中 Alt+右鍵點擊物品可加入或移出清單。在商人處按住 Shift 可略過。",
  ["Alt+right-click to take it off"] = "Alt+右鍵點擊以移除",
