  ["Altar of Hakkar"] = "哈卡祭壇",
  ["Alterac Valley (Battleground)"] = "奧特蘭克山谷（戰場）",
  ["Ambassador Malcin waits outside the entrance of Razorfen Downs. The quest also appears under Razorfen Kraul, where the Small Scroll that starts it drops."] = "瑪爾辛大使在剃刀高地入口外等著。這個任務也會出現在剃刀沼澤底下，開始任務的小卷軸就是在那裡掉落。",
