  ["An Enticing Offer"] = "誘人的提議",
  ["An ancient titan vault in the Badlands, dug up by the Explorers' League and the Dark Iron dwarves. Archaedas guards the Discs of Norgannon."] = "荒蕪之地的一座古老泰坦寶庫，被探險者協會和黑鐵矮人挖開。阿札達斯守護著諾甘農圓盤。",
  ["An error was caught and the feature skipped. Type /ofa errors to see it (for a bug report)."] = "抓到一個錯誤，已略過那個功能。輸入 /ofa errors 查看（回報錯誤用）。",
  ["Anara Chillwind"] = "安娜拉·寒風",
