  ["Angelique Butler"] = "安潔莉克·巴特勒",
  ["Answer Parqual Fintallas' question successfully and then speak to him again. He will remain in the Undercity until you are ready."] = "成功回答帕科瓦·芬塔拉斯的問題，然後再次和他對話。他會一直在幽暗城等你回答問題。",
  ["Any buff name works, also without a suggestion - the list only helps. The name as in your spellbook, e.g. \"Demon Skin\". Flasks and elixirs: the name of their buff (e.g. \"Supreme Power\"). Weapon oils, sharpening stones and poisons: type their name (\"sh\" shows the sharpening stones) and pick \"(main hand)\", or add \"(off hand)\" for the other weapon; a click on the reminder uses it on that weapon when it is in your bags. Seconds: 5 - 3600."] = "任何增益效果名稱都可以，沒有建議也可以——清單只是輔助。名稱照法術書上的寫，例如「惡魔皮膚」。精煉藥劑和藥劑：寫它們的增益效果名稱（例如「至高能量」）。武器油、磨刀石和毒藥：輸入名稱（輸入「磨」會列出磨刀石）並選「（主手）」，或加上「（副手）」用於另一把武器；當它在你背包裡時，點提醒就會對那把武器使用。秒數：5～3600。",
