  ["Breathes lightning, instantly dealing Nature damage to a single target."] = "噴吐閃電，立即對單一目標造成自然傷害。",
  ["Breathes molten lava at 2 nearby enemies, instantly dealing Fire damage and reducing the target's casting speed by 25% for 10 sec."] = "對附近2名敵人噴吐熔岩，立即造成火焰傷害，並使目標的施法速度降低25%，持續10秒。",
  ["Brewer's Trade"] = "釀酒師的生意",
  ["Brewmancer Nightcap"] = "釀酒師睡帽",
