  ["Brilliant Watcher's Signet"] = "觀察者才智璽戒",
  ["Bring 10 Elixirs of Shadow Power to Gorzeeki Wildeyes in the Burning Steppes."] = "把10瓶暗影之力藥劑交給燃燒平原的戈瑟奇·邪眼。",
  ["Bring 10 Motes of Unstable Magic to Archmage Celindra in Dalaran."] = "把10個不穩定的魔法微粒交給達拉然的大法師瑟琳卓。",
  ["Bring 10 bottles of Silvermoon Shimmerwine to Arille Azuregaze in Dalaran city."] = "把10瓶銀月閃光酒交給達拉然城的艾立爾·蒼凝。",
  ["Bring 3 Arcanite Bar to Gorzeeki in the Burning Steppes."] = "把3塊奧金錠交給燃燒平原的戈瑟奇·邪眼。",
  ["Bring 35 Black Dragonscales to Gorzeeki Wildeyes in the Burning Steppes."] = "把35塊黑龍鱗片交給燃燒平原的戈瑟奇·邪眼。",
  ["Bring 4 Skullsplitter Fetishes to Brother Nimetz at the Rebel Camp."] = "給叛軍營地的尼麥茲修士帶回4只劈顱食人妖的神像。",
  ["Bring 4 Thick Leather and 12 Iron Bar to Kreza Darkthorn."] = "把4張厚皮和12塊鐵錠交給克雷札·暗棘。",
  ["Bring 4 Thick Leather and 12 Iron Bars to Alphonse Dumas."] = "把4張厚皮和12塊鐵錠交給阿方斯·杜馬斯。",
  ["Bring 6 Large Brilliant Shards and 25 Dark Iron Ore to Gorzeeki in the Burning Steppes."] = "把6份大塊魔光碎片和25塊黑鐵礦石交給燃燒平原的戈瑟奇·邪眼。",
  ["Bring 7 Jungle Remedies and 1 Venom Fern Extract to Sergeant Yohwa at the Rebel Camp."] = "給反抗軍營地裡的尤瓦中士帶回7份密林藥劑和1份毒草汁液。",
  ["Bring Back a Bang"] = "帶點轟動回來",
  ["Bring Darkreaver's Head to Sagorne Creststrider in the Valley of Wisdom, Orgrimmar."] = "把達克雷爾的頭顱交給奧格瑞瑪智慧谷的薩格尼·擎峰。",
  ["Bring Doomrigger's Clasp to Mayara Brightwing in the Burning Steppes."] = "將末日扣環交給燃燒平原的瑪亞拉·布萊特文。",
  ["Bring Loremaster Dibbs' I'lalai Translations to Historian Karnik in Ironforge."] = "將博學大師迪布斯的伊拉萊譯文交給鐵爐堡的歷史學家卡尼克。",
  ["Bring Mayena Earthseeker a Moist Crystal, a Charged Crystal, a Noxious Crystal and a Fiery Crystal from Shaper's Terrace."] = "從塑造者平臺帶一個潮濕的水晶、一個充能的水晶、一個劇毒的水晶和一個熾熱的水晶給梅耶娜·尋地者。",
  ["Bring Ott's Masterwork to Trevan Rol in Silverpine Forest."] = "把奧特的傑作帶去給銀松森林的崔凡‧羅爾。",
  ["Bring Rethiel the Greenwarden 9 Crude Flints."] = "給綠色守衛者雷希耶爾帶回9塊粗製打火石。",
  ["Bring Riptear's Heart to Deathguard Linnea."] = "將撕裂者的心臟交給亡靈守衛林奈。",
  ["Bring Thermaplugg's Engineering Notes to Nogg at the Valley of Honor in Orgrimmar."] = "把瑟瑪普拉格的工程筆記交給奧格瑪榮譽谷的諾格。",
  ["Bring a Libram of Focus, 1 Pristine Black Diamond, 4 Large Brilliant Shards, and 2 Skin of Shadow to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Focus."] = "將專注聖典、1塊原始黑鑽石、4份大塊魔光碎片和2張暗影之皮交給厄運之槌的博學者萊德羅斯，以換取一份專注秘藥。",
  ["Bring a Libram of Protection, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 1 Frayed Abomination Stitching to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Protection."] = "將防護聖典、1塊原始黑鑽石、2份大塊魔光碎片和1份磨損的憎惡縫合線交給厄運之槌的博學者萊德羅斯，以換取一份防護秘藥。",
  ["Bring a Libram of Rapidity, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 2 Blood of Heroes to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Rapidity."] = "將急速聖典、1塊原始黑鑽石、2份大塊魔光碎片和2份英雄之血交給厄運之槌的博學者萊德羅斯，以換取一份急速秘藥。",
  ["Bring a Tablet Shard to Kin'weelay at the Grom'gol Base Camp."] = "給格羅姆高營地裡的肯維雷帶回一塊石板碎片。",
  ["Bring an Enchanted Thorium Bar, 5 Crystal Restore, and a Vial of Dire Water to Aurora Skycaller near the Northpass Tower in Eastern Plaguelands."] = "給東瘟疫之地的奧蘿拉帶去一塊魔化瑟銀錠、5塊恢復水晶，以及一小瓶恐怖之水。",
  ["Bring the Blackfathom Pearl to Bashana Runetotem in Thunder Bluff."] = "把黑暗深淵珍珠交給雷霆崖的巴珊娜·符文圖騰。",
  ["Bring the Blackfathom Pearl to Dawnwatcher Selgorm in Darnassus."] = "把黑暗深淵珍珠交給達納蘇斯的哨兵塞爾高姆。",
  ["Bring the Blood-Stained Letter to Orphan Matron Nightingale in Stormwind City."] = "把染血信件交給暴風城的孤兒院院長南丁格爾。",
  ["Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Nogg in Orgrimmar."] = "將閃亮的金戒指、1塊銀錠、1塊綠瑪瑙和30個銀幣交給奧格瑞瑪的諾格。",
  ["Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Talvash del Kissel in Ironforge."] = "將閃亮的金戒指、1塊銀錠、1塊綠瑪瑙和30個銀幣交給鐵爐堡的塔瓦斯德·基瑟爾。",
  ["Bring the Claws of the Great Bear and the Tusks of the Unbroken to Ogtinc, in Azshara."] = "把巨熊之爪和不屈者的獠牙交給艾薩拉的歐格汀克。",
  ["Bring the Crest of Lordaeron to Oran Snakewrithe in Undercity."] = "把羅德隆紋章交給幽暗城的奧蘭·蛇蜷。",
  ["Bring the Head of the Baron to the body of Othmar in the Undercity."] = "到幽暗城，把男爵的頭放在歐斯瑪的遺體旁。",
  ["Bring the I'lalai Fetish to Abra Cadabra in Dalaran."] = "將伊拉萊神像交給達拉然的阿布拉‧卡達布拉。",
  ["Bring the Inert Scourgestone to Commander Ashlan Valorfist in Chillwind Point."] = "將惰性天災石交給冰風崗的指揮官阿什拉姆·瓦羅菲斯特。",
  ["Bring the Orders from the Grand Crusader back to Katherine the Pure."] = "把來自大十字軍的命令帶回去給純潔的凱薩琳。",
  ["Bring the Remote Detonator Kit to Sprite Jumpsprocket in the Dwarven District of Stormwind."] = "把遙控引爆器組件交給暴風城矮人區的斯普萊特·跳鏈。",
  ["Bring the Satchel of Cursed Mementos to Ashe Amberhall in Farholde Keep."] = "將受詛咒的紀念物背袋帶去給遠境堡要塞的艾希‧安珀荷。",
  ["Bring the Satchel of Mementos to Melanie Sable."] = "把紀念品背包交給梅蘭妮·薩布爾。",
  ["Bring the Titan Relic to High Explorer Magellas in Ironforge's Hall of Explorers."] = "把泰坦聖物交給鐵爐堡探險者大廳的首席探險家麥哲倫。",
  ["Bring the Titan Relic to Prospector Whelgar in the Wetlands excavation site."] = "把泰坦聖物交給濕地挖掘場的勘察員維爾加。",
  ["Bring the pieces for the spirit totem to Bath'rah the Windwatcher."] = "將靈魂圖騰所需的材料交給捕風者巴斯拉。",
  ["Bring the voodoo feathers to Ashlam Valorfist."] = "前往沈沒的神廟，從巨魔守護者們身上取得巫毒羽毛，然後把它們交給阿什拉姆·瓦羅菲斯特。",
  ["Bring the voodoo feathers to Bath'rah the Windwatcher."] = "將巫毒羽毛交給捕風者巴斯拉。",
