  ["Chance on Hit: Immobilizes the target and lowers their armor by 100 for 10 sec. (Proc chance: 5%)"] = "擊中時可能：使目標定身並使其護甲值降低100點，持續10秒。（觸發機率：5%）",
  ["Chance on damaging spell to allow 15% of your Mana regeneration to continue while casting for 15 sec. Mana regen amount is doubled in Strongholds and Cities."] = "傷害法術有一定機率讓你在15秒內施法時仍保有15%的法力恢復速度。在據點和城市中法力恢復量加倍。",
  ["Chance on damaging spell to summon an Arcane elemental to aid you in combat."] = "施放傷害性法術後，有機率召喚一個秘法元素協助你戰鬥。",
  ["Chance on hit to gain 5% attack speed for 10 sec. Attacks while no allies are within 20 yds are 2 times as likely to activate this effect."] = "命中時有機率使攻擊速度提高5%，持續10秒。附近20碼範圍內沒有盟友時，攻擊觸發此效果的機率提高2倍。",
  ["Chance on melee attack to heal for 88 to 132 and generate 10 Rage"] = "近戰攻擊時有一定機率恢復88到132點生命力並產生10點怒氣",
  ["Chance on melee attack to heal you for 88 to 132."] = "近戰攻擊時有一定機率為你恢復88到132點生命力。",
  ["Chance on melee attack to increase your damage and healing done by magical spells and effects by up to 65 for 10 sec."] = "有機會在進行近戰攻擊時，提高魔法法術和效果所造成的傷害和治療效果，最多65點，持續10秒。",
  ["Chance on melee attack to lash the target, inflicting 140 Shadow damage."] = "有機會於近戰攻擊時鞭笞目標，造成140點暗影傷害。",
  ["Chance on melee attack to restore 20 Energy."] = "有機會於近戰攻擊時恢復20點能量。",
  ["Chance on melee autoattack and spellcast to increase your damage and healing done by magical spells and effects by up to 65 for 10 sec."] = "近戰自動攻擊和施放法術，有機率使你的魔法法術和效果造成的傷害和治療效果最多提高65點，持續10秒。",
  ["Chance on melee swing to become Angry, increasing Strength by 50 for 10 sec. (100ms cooldown)"] = "近戰攻擊時有一定機率進入憤怒狀態，力量提高50點，持續10秒。（冷卻0.1秒）",
  ["Chance on spell cast to increase your damage and healing by up to 65 for 10 sec. (Proc chance: 4%)"] = "施法時有一定機率使你的傷害和治療效果提高最多65點，持續10秒。（觸發機率：4%）",
  ["Chance on spellcast to restore 200 Mana, on melee attack to regenerate 20 Energy over 5 sec, and when struck by a melee attack to generate 10 Rage."] = "施放法術有機率為你恢復200點法力，近戰自動攻擊有機率在5秒內為你恢復20點能量，而被近戰攻擊命中有機率產生10點怒氣。",
