  ["Charges an enemy, immobilizes it for 1 sec, and adds 130 melee attack power to the boar's next attack."] = "向敵人發起衝鋒，使其在1秒內無法移動，並使你的下一次野豬攻擊獲得130近戰攻擊強度加成。",
  ["Charges an enemy, immobilizes it for 1 sec, and adds 204 melee attack power to the boar's next attack."] = "向敵人發起衝鋒，使其在1秒內無法移動，並使你的下一次野豬攻擊獲得204近戰攻擊強度加成。",
  ["Charges an enemy, immobilizes it for 1 sec, and adds 294 melee attack power to the boar's next attack."] = "向敵人發起衝鋒，使其在1秒內無法移動，並使你的下一次野豬攻擊獲得294近戰攻擊強度加成。",
  ["Charges an enemy, immobilizes it for 1 sec, and adds 430 melee attack power to the boar's next attack."] = "向敵人發起衝鋒，使其在1秒內無法移動，並使你的下一次野豬攻擊獲得430近戰攻擊強度加成。",
  ["Charges an enemy, immobilizes it for 1 sec, and adds 520 melee attack power to the boar's next attack."] = "向敵人發起衝鋒，使其在1秒內無法移動，並使你的下一次野豬攻擊獲得520近戰攻擊強度加成。",
  ["Charges an enemy, immobilizes it for 1 sec, and adds 66 melee attack power to the boar's next attack."] = "向敵人發起衝鋒，使其在1秒內無法移動，並使你的下一次野豬攻擊獲得66近戰攻擊強度加成。",
  ["Charges an enemy, immobilizes it for 1 sec, and adds melee attack power to the boar's next attack."] = "衝向一名敵人，使其定身1秒，並使野豬的下一次攻擊增加近戰攻擊強度。",
