  ["Click Search to find players who know this recipe."] = "點「搜尋」尋找會這個配方的玩家。",
  ["Click Search to find the recipes that sell for more than their materials cost."] = "點「搜尋」找出賣價比材料成本高的配方。",
  ["Click a buff in the list to remove it."] = "點清單中的增益效果即可移除。",
  ["Click a reagent in the recipe details: made with a profession, the nearest vendors, herbs, ore and fishing, or the nearest mobs that drop it."] = "在配方詳細資料中點材料：會顯示用哪個專業技能製作、最近的商人、草藥、礦和釣魚地點，或最近會掉落它的怪物。",
  ["Click again to destroy"] = "再點一次以摧毀",
  ["Click again to reverse, a third time for the default order."] = "再點一次反向排序，點第三次回到預設順序。",
  ["Click it for a quick list: Map Landmarks and its parts, Remove Fog and the dungeon map. It sits below other addons' buttons there (RareScanner ...)."] = "點它會出現快速清單：地圖地標及其細項、移除迷霧和地城地圖。它會排在其他插件按鈕的下方（RareScanner……）。",
  ["Click one to have it reported again."] = "點一個讓它再次被提醒。",
  ["Click the icon to cast it again."] = "點擊圖示再施放一次。",
  ["Click the star on an enchant to add it."] = "點附魔上的星星把它加入。",
  ["Click the star on an item to add it."] = "點物品上的星星把它加入。",
  ["Click to choose a colour."] = "點擊選顏色。",
  ["Click to open the ability"] = "點擊打開這個技能",
  ["Click to open the dungeon in OneForAll."] = "點擊在 OneForAll 中打開這個地城。",
  ["Click: Open / close"] = "點擊：開啟／關閉",
  ["Click: map icons, quest icons, Remove Fog and the dungeon map."] = "點擊：地圖圖示、任務圖示、移除迷霧和地城地圖。",
  ["Click: open the recipe in All recipes."] = "點擊：在「所有配方」裡打開這個配方。",
  ["Click: select for the shopping list and the Crafting List. Right-click: open the recipe in All recipes."] = "點擊：選進購物清單和製作清單。右鍵：在「所有配方」裡打開這個配方。",
  ["Click: show its loot in Bosses & Loot."] = "點擊：在「首領與戰利品」中顯示它的戰利品。",
  ["Click: what you can put on this item (enchants, armor kits and the like)."] = "點擊：可以放在這件物品上的東西（附魔、護甲片之類）。",
  ["Cloak Enchants"] = "披風附魔",
  ["Cloak of the Fleshborer"] = "破肉者披風",
  ["Cloak of the Tidemistress"] = "潮汐女士披風",
  ["Cloaks"] = "披風",
  ["Clock"] = "時鐘",
  ["Close"] = "關閉",
  ["Cloth Headgear"] = "布甲頭部",
  ["Collapse"] = "收合",
  ["Collect 'Rumi of Gnomeregan: The Collected Works' and bring it to Garion Wendell in Stormwind."] = "取得《諾姆瑞根的烏米：作品全集》，交給暴風城的加利昂‧溫德爾。",
  ["Collect 10 Bloodied Insignias and take them to General Marcus Jonathan in Stormwind City."] = "收集10枚染血的徽章，交給暴風城的馬庫斯·喬納森將軍。",
  ["Collect 10 Voodoo Infused Artifacts from Saltseer pirates in the Drowned City."] = "從沉沒之城的鹽占海盜身上收集10個巫毒灌注文物。",
  ["Collect 15 Bloodpetals and return to Muigin."] = "從安戈洛爾環形山的血瓣花猛擊者和血瓣花掠奪者身上收集15個血瓣花，然後向穆爾金回復。",
  ["Collect 15 Cultist Ears from the Twilight's Hammer in Krol'dok Stronghold."] = "在克羅多克要塞從暮光之錘成員身上收集15個教徒耳朵。",
  ["Collect 15 Partially Digested Journal Pages from the Shaper's Terrace."] = "在塑造者殿堂收集15張部分消化的日記書頁。",
  ["Collect 20 Minion's Scourgestones and bring them to High Priest Thel'danis in the Western Plaguelands."] = "收集20個爪牙的天災石，並將它們交給西瘟疫之地的高階牧師賽爾丹尼斯。",
  ["Collect 5 I'lalai Fetishes from trolls in the Drowned City."] = "從沉沒之城的食人妖身上收集5個伊拉萊神像。",
  ["Collect 5 Twilight Pages from within Sunnyglade for Ashe Amberall in Farholde Keep."] = "前往陽光林地，為遠境堡要塞的艾希‧安珀荷收集5份暮光書頁。",
  ["Collect 5 samples of Atal'ai Haze, then return to Muigin in Un'Goro Crater."] = "收集5份阿塔萊之霧的樣本，然後向安戈洛環形山的穆爾金復命。",
  ["Collect 7 Gnomeregan Archival Data cards from around Gnomeregan, then deliver them to Jemma Quikswitch in Ironforge."] = "在諾姆瑞根附近收集7張諾姆瑞根檔案資料卡，然後交給鐵爐堡的潔瑪‧迅移。",
  ["Collect 8 Cultist Bangles from the Twilight's Hammer in Krol'dok Stronghold."] = "在克羅多克要塞從暮光之錘成員身上收集8個教徒手鐲。",
  ["Collect 8 Suspicious Industrial Supplies from Moonbrook."] = "從月溪鎮收集8份可疑的工業補給品。",
  ["Collect Skullthumper from Klunk for Clugfist in Bolder'ok."] = "幫博德羅克的鈍拳從克魯克身上取回碎顱錘。",
  ["Collect a Fel Infused Blossom from the City of Dalaran for Shylamiir in Stormwind City."] = "在達拉然城收集一朵魔能灌注之花，交給暴風城的莎拉米爾。",
  ["Collect a Toxic Skullcap from Tawny Grisette in the Trade Quarter, Blisterweed near the Herbalism Trainer, and Essence of Agony from the poison vendor in the Rogues' Quarter for Master Apothecary Faranell in Undercity."] = "幫幽暗城的大藥劑師法拉尼爾向貿易區的塔文‧格瑞斯特收集劇毒顱帽，在草藥學訓練師附近收集灼蝕草，以及向盜賊區的毒藥商購買苦楚精華。",
  ["Collect a sample of air, fire, earth and water for Bath'rah the Windwatcher."] = "為捕風者巴斯拉收集一份空氣樣本、一份火元素樣本、一份土元素樣本和一份水元素樣本。",
  ["Collect minimap buttons"] = "收集小地圖按鈕",
  ["Collect the Arcane Mote for the Image of Archmage Modera near the City of Dalaran."] = "為達拉然城附近的大法師莫德菈的影像收集秘法微粒。",
  ["Collect the Arcane Mote in the City of Dalaran for Magus Wordeen Voidglare in Tarren Mill."] = "幫塔倫米爾的魔導師沃迪恩‧虛無之光到達拉然城收集秘法微粒。",
  ["Collect the Founding of Dalaran from the City of Dalaran for Rexxie Copperclutch near the sewer entrance."] = "在達拉然城取得《達拉然的建立》，交給下水道入口附近的雷克希·銅爪。",
  ["Collect the Head of the Baron in the Ruins of Lordaeron and bring it back to Captain Truman."] = "在羅德隆廢墟取得男爵的頭顱，帶回去給杜魯門隊長。",
  ["Collect the cards outside the instance: the undead miners walk the side tunnel on the way in."] = "在副本外收集卡片：不死礦工在進去途中的側邊隧道裡走動。",
