  ["Defeat 8 Seeking Remnants, 8 Saturated Remnants, and 8 Mana Echoes inside the City of Dalaran for Archmage Modera outside of Dalaran."] = "為達拉然外的大法師莫德菈在達拉然城內擊敗8個尋找的殘渣、8個浸透的殘渣，以及8個法力回音。",
  ["Defeat 8 Twilight Fanatics, 8 Twilight Corrupters, and 8 Twilight Champions within the Twilight's Shroud for Da'grosh."] = "為達羅許在暮光之罩中擊敗8個暮光狂熱者、8個暮光腐蝕者，以及8個暮光勇士。",
  ["Defeat 8 Twilight Fanatics, 8 Twilight Corrupters, and 8 Twilight Champions within the Twilight's Shroud for Sergeant Riftan."] = "為瑞夫坦中士在暮光之罩中擊敗8個暮光狂熱者、8個暮光腐蝕者，以及8個暮光勇士。",
