  ["Ends the Defias Brotherhood chain of Gryan Stoutmantle. The earlier steps in Westfall are required."] = "完成格里安·斯托曼的迪菲亞兄弟會任務系列。必須先完成西部荒野的前面幾步。",
  ["Engineering Trainer"] = "工程學訓練師",
  ["Entangles an enemy in a corrosive web, immobilizing them and dealing 12 Nature damage over 4 sec."] = "以腐蝕之網糾纏敵人，使其無法移動，並在4秒內造成12點自然傷害。",
  ["Entangles an enemy in a corrosive web, immobilizing them and dealing 20 Nature damage over 4 sec."] = "以腐蝕之網糾纏敵人，使其無法移動，並在4秒內造成20點自然傷害。",
  ["Entangles an enemy in a corrosive web, immobilizing them and dealing 28 Nature damage over 4 sec."] = "以腐蝕之網糾纏敵人，使其無法移動，並在4秒內造成28點自然傷害。",
  ["Entangles an enemy in a corrosive web, immobilizing them and dealing 40 Nature damage over 4 sec."] = "以腐蝕之網糾纏敵人，使其無法移動，並在4秒內造成40點自然傷害。",
  ["Entangles an enemy in a corrosive web, immobilizing them and dealing 52 Nature damage over 4 sec."] = "以腐蝕之網糾纏敵人，使其無法移動，並在4秒內造成52點自然傷害。",
  ["Entangles an enemy in a corrosive web, immobilizing them and dealing Nature damage over 4 sec."] = "用腐蝕性的蛛網纏住敵人，使其定身並在4秒內造成自然傷害。",
  ["Enter Alcaz Prison and collect 8 Blood Red Bandanas from the human guards there."] = "進入奧卡茲監獄，從那裡的人類守衛身上收集8條血紅頭巾。",
  ["Enter Alcaz Prison and learn what became of the King of Stormwind."] = "進入奧卡茲監獄，查明暴風城國王的下落。",
  ["Enter Blackmaw Hold and recover 5 Blackmaw Pouches for Ekkal at the Ruins of Eldarath in Azshara."] = "進入黑喉要塞，幫艾薩拉埃達拉斯廢墟的艾卡爾取回5個黑喉袋子。",
  ["Enter Dire Maul East through the Broken Commons; Pusillin waits near the entrance."] = "從破碎大廳進入厄運之槌東區；普希林在入口附近等著。",
  ["Enter the Alcaz Prison and find Commander Folkar."] = "進入奧卡茲監獄，找到指揮官佛卡爾。",
  ["Enter the Alcaz Prison and slay 15  Strashasz Soldiers, 8 Strashaz Enchantresses, and bring the head of Tidemistress Ca'zass to Sully McCleary."] = "進入奧卡茲監獄並殺死15個斯塔莎茲士兵、8個斯塔莎茲女巫師，並將卡薩絲小姐的頭顱帶去給蘇利‧麥拉利。",
  ["Enter the Alcaz Prison and slay 15 Strashasz Soldiers, 8 Strashaz Enchantresses, and bring the head of Tidemistress Ca'zass to Sergeant Ulka."] = "進入奧卡茲監獄並殺死15個斯塔莎茲士兵、8個斯塔莎茲女巫師，並將卡薩絲小姐的頭顱帶去給烏爾卡中士。",
