  ["Escort quest: Belnistrasz must survive his ritual at the idol. Everyone in the group needs Scourge of the Downs done first."] = "護送任務：貝尼斯特拉茲必須在神像前完成儀式並活下來。隊伍中每個人都要先完成「剃刀高地的天譴軍團」。",
