  ["Find Bijou's Belongings and return them to her. You recall her mentioning that she stashed them on the bottom floor of the city. "] = "找到比修的物品並還給她。你記得她說過，她把東西藏在城市的最底層。 ",
  ["Find Da'grosh in the hills west of Rog'mar."] = "到羅格瑪西邊的山丘找達羅許。",
  ["Find Interesting Landmarks in Shaper's Terrace and fill out the explorer's map at each."] = "在塑造者殿堂尋找有趣的地標，並在各個地標處繪製探險者地圖。",
  ["Find Loremaster Dibbs in Southshore and bring him the Savage Coast Report Bundle."] = "到南海鎮找博學大師迪布斯，將一捆野人海岸報告交給他。",
  ["Find Sergeant Danneth somewhere in the Serpent's Coil caverns southeast of Nethergarde Keep."] = "在守望堡東南方的盤蛇谷洞穴裡找到丹尼斯中士。",
  ["Find Sergeant Riftan near the Twilight's Shroud to the west."] = "到西邊的暮光之罩附近找瑞夫坦中士。",
  ["Find Starfall in Winterspring and speak with Wynd Nightchaser."] = "找到冬泉谷的墜星村，在那裡與維恩德·夜風談一談。",
  ["Find The Eye of Bhossca inside of the Scarlet Monastery. Then, return it to C's dead drop near Pyrewood Village. You must complete the job alone."] = "在血色修道院裡找到波斯卡之眼，然後把它放回焚木村附近 C 的密件藏匿處。你必須獨自完成這件工作。",
  ["Find The Horn of Xelthos inside of Shadowfang Keep. Then, return it to C's dead drop near Pyrewood Village."] = "在影牙城堡裡找到澤索司號角，然後把它送回焚木村附近 C 的密件點。",
  ["Find The Horn of Xelthos inside of Shadowfang Keep. Then, return it to C's dead drop near Pyrewood Village. You must complete the job alone."] = "在影牙城堡中尋找澤索司號角，接著再回到 C 於焚木村附近的密件藏匿處。你必須獨自一人完成任務。",
  ["Find The Talisman of Kazdor inside of Zul'Farrak. Then, bring it to Fahrad at Ravenholdt Manor. You must complete the job alone."] = "在祖爾法拉克裡找到卡茲多咒符，然後把它帶去拉文霍德莊園給法拉德。你必須獨自完成這項工作。",
  ["Find Veyric Thundervein in Arathi Highlands."] = "到阿拉希高地找維里克‧雷鎚。",
  ["Find Woodwyrd in the Forlorn Gardens at Shen'dralas in the Desolace."] = "在淒涼之地申德拉斯的淒涼花園找到伍德維德。",
  ["Find a way into Dalaran along the Lordamere Lake."] = "沿著洛丹米爾湖尋找進入達拉然的路。",
  ["Find missing ogres in the caves beneath Sunnyglade for Clubtoe."] = "幫棒趾在陽光林地之下的洞穴找到失蹤的巨魔。",
  ["Find someone in Farholde Keep who may know about the mould."] = "在遠境堡要塞尋找可能知道這個模具的人。",
  ["Find someone in Rog'mar who may know about the mould."] = "在羅格瑪尋找可能知道這個模具的人。",
  ["Find the 4 tablets and bring their legends back to Brother Nimetz."] = "找到4塊石板並將上面的內容帶回去交給尼麥茲修士。",
  ["Find the Sacred Highborne Writings in the Temple of Zin-Malor in Azshara, and bring them to Aurora Skycaller near the Northpass Tower in Eastern Plaguelands."] = "在艾薩拉的辛瑪洛神殿裡找到神聖的上層精靈筆跡，並將它帶給位於東瘟疫之地的北地哨塔附近的奧蘿拉。",
  ["Find the Totem of Ursoc and the Totem of Ursol inside Blackmaw Hold. Then, return them to Lorekeeper Nok at Ursolan."] = "在黑喉要塞尋找厄索克圖騰和厄索爾圖騰。然後將它們帶回去給厄索蘭的博識者諾克。",
  ["Find the forge hidden in the Deadmines, and plant the Extra-Destructive Explosives nearby. Then, meet up with Alba Fairmoon at the Deadmines exit."] = "找到藏在死亡礦坑裡的熔爐，在附近放置超強破壞炸藥。然後到死亡礦坑出口和艾芭‧皎月會合。",
  ["Find the missing Kor'kron Elites."] = "找到失蹤的柯爾克隆精英。",
  ["Find the owner of the Ancient Petrified Leaf. Good luck, <Name>; It's a big world."] = "找到遠古石葉的主人。祝你好運，<名字>。這個世界是很大的。",
  ["Find the owner of the Feathered Charm Necklace."] = "找到羽飾護符項鍊的主人。",
  ["Find the traitors and recover their artifacts, then return to Magus Voidglare in Tarren Mill."] = "找到被遺忘者的叛徒，取回他們偷走的神器，然後回到塔倫米爾去見大法師沃迪恩·伍德格萊爾。",
  ["Find what awaits you."] = "去看看有什麼在等著你。",
  ["Finding Warmth"] = "尋找溫暖",
  ["Finds OneForAll users outside your guild who know a recipe."] = "找出公會以外會某個配方的 OneForAll 使用者。",
