  ["For buffs that last longer than 2 minutes. It comes 1 second later, not in combat, at most once every 5 minutes per player. Your target is not changed. /ofa thanks shows the last buffs."] = "針對持續超過 2 分鐘的增益效果。會在 1 秒後送出，不在戰鬥中，對同一位玩家每 5 分鐘最多一次。不會改變你的目標。/ofa thanks 可看最近的增益效果。",
  ["For spells you use in a low rank on purpose. This rank is not reported again; Quality of Life > Spells lists the kept ranks."] = "給你刻意使用低等級的法術用。這個等級之後不會再提醒；「生活便利 > 法術」會列出保留的等級。",
