  ["Gather 10 Brinescale Tridents from Brinescale Skirmishers."] = "從海鱗爭鬥者身上收集10把海鱗三叉戟。",
  ["Gather 10 Nordrassil Root Caps inside Blackmaw Hold for Mathrengyl Bearwalker in Darnassus."] = "為達納蘇斯的瑪斯雷·馭熊者，在黑喉要塞裡收集10個諾達希爾根帽。",
