  ["Girdle of Extracted Answers"] = "逼供腰帶",
  ["Gives the Paladin a chance on every melee hit to heal your party for 189 to 211."] = "使聖騎士每次近戰命中時有一定機率為你的隊伍恢復189到211點生命力。",
  ["Gives the Rogue a chance to inflict 283 to 317 damage on the target and heal the Rogue for 50 health every 1 sec. for 6 sec. on a melee hit."] = "使盜賊近戰命中時有一定機率對目標造成283到317點傷害，並在6秒內每1秒為盜賊恢復50點生命力。",
  ["Gives you a 20% chance to generate an additional Rage point whenever damage is dealt to you. (Proc chance: 20%)"] = "每次受到傷害時，有20%的機率額外產生1點怒氣。（觸發機率：20%）",
  ["Gives your Mage Armor a chance when struck by a harmful spell to increase resistance against that school of magic by 35 for 30 sec. (Proc chance: 20%)"] = "使你的魔甲術在受到有害法術攻擊時，有一定機率使你對該系魔法的抗性提高35點，持續30秒。（觸發機率：20%）",
  ["Gleaning Our Future"] = "探尋我們的未來",
