  ["Go below 10 to switch it off (then the game's own setting is kept)."] = "調到 10 以下即關閉（改用遊戲本身的設定）。",
  ["Go to Dire Maul East"] = "前往厄運之槌東區",
  ["Goblin Lockpicks"] = "哥布林開鎖器",
  ["Gordok Commons, taken over by the Gordok ogres. Kill King Gordok and Captain Kromcrush makes you the new king, but leave the guards alive for a richer tribute."] = "戈多克大廳，被戈多克食人魔佔領。殺死戈多克大王後克羅卡斯會讓你成為新國王，但要留下守衛活口才能拿到更豐富的貢品。",
  ["Gortek the Apprentice"] = "學徒戈泰克",
  ["Got it"] = "知道了",
  ["Grabs an enemy's weapon with its talons, causing damage and disarming them for 4 sec."] = "用利爪抓住敵人的武器，造成傷害並繳械4秒。",
  ["Grace of An'she and Mu'sha"] = "安希與穆莎的恩典",
  ["Grand Crusader Dathrohan turns into the dreadlord Balnazzar during the fight."] = "大十字軍戰士達索漢在戰鬥中會變成恐懼魔王巴納札爾。",
  ["Grand Marshal's Weapons"] = "總元帥的武器",
  ["Grants +5% increased spell hit chance for 20 sec when one of your spells is resisted."] = "當你的法術被抵抗後，法術命中率提高5%，持續20秒。",
  ["Grants a chance when struck in combat to increase damage and healing done by magical spells and effects by up to 70 for 10 sec. (Proc chance: 15%, 1m cooldown)"] = "受到攻擊時有一定機率使法術和魔法效果所造成的傷害和治療效果提高最多70點，持續10秒。（觸發機率：15%，冷卻1分鐘）",
  ["Grants a small chance when ranged or melee damage is dealt to infuse the wielder with a blessing from the Primal Gods. Ranged and melee attack power increased by 300 for 12 seconds. (Proc chance: 1%, 4m cooldown)"] = "造成遠程或近戰傷害時有小機率讓使用者獲得原始之神的祝福：遠程和近戰攻擊強度提高300點，持續12秒。（觸發機率：1%，冷卻4分鐘）",
  ["Grants your healing spells a chance to heal for an additional 40 Health every 3 sec for 15 sec. (2s cooldown)"] = "你的治療法術有一定機率在15秒內每3秒額外恢復40點生命力。（冷卻2秒）",
  ["Grants your melee attacks a 5% chance when striking from behind to hit a vital point, causing the target to Bleed for 68 to 83 Physical damage over 5 sec. (Proc chance: 5%)"] = "使你從背後發動的近戰攻擊有5%的機率命中要害，使目標流血，在5秒內受到68到83點物理傷害。（觸發機率：5%）",
  ["Grants your melee attacks a chance to inflict Dream Venom, stunning the target for 1 sec."] = "你的近戰攻擊有一定機率施加夢境毒液，使目標昏迷1秒。",
  ["Grave robbers have forced their way into the old burial halls of the dwarven kings deep below Ironforge."] = "盜墓者強行闖入了鐵爐堡深處矮人諸王的古老墓穴。",
