  ["High Order (Alliance) see the Ley Lines for Read Leyline (Attuned: 100% regeneration for 1 hour), Windshapers (Horde) the Elemental Convergences for Skysight (Charged: 30% movement speed for 1 hour). On by default for Skyborne; other races see the spots of their faction when they switch it on. Locations from the addon \"Skyborne Leyline & Convergence Marker\" by tr0tsky."] = "高天盟（聯盟）看得到用於「解讀地脈」的地脈（同調：1 小時 100% 回復），塑風者（部落）看得到用於「天之視覺」的元素匯流點（充能：1 小時 30% 移動速度）。天裔精靈預設開啟；其他種族開啟後會看到自己陣營的地點。地點資料來自 tr0tsky 的插件「Skyborne Leyline & Convergence Marker」。",
