  ["Increases the radius of effect of your beneficial Air and Earth totems by 10 yds."] = "使你增益性風之圖騰和大地圖騰的效果範圍提高10碼。",
  ["Increases the radius of effect of your beneficial Fire and Water totems by 10 yds."] = "使你增益性火焰圖騰和水之圖騰的效果範圍提高10碼。",
  ["Increases the range of your Mend Pet spell by 50% and the effect by 10%.  Also reduces the cost by 30%."] = "使你的治療寵物技能的施放距離增長50%。效果提高10%，法力消耗降低30%。",
  ["Increases the threat generated by Sunder Armor by 15%."] = "使破甲攻擊所造成的威脅值提高15%。",
  ["Increases your attack speed and casting speed by 1%."] = "使你的攻擊速度和施法速度提高1%。",
  ["Increases your chance of a critical hit with Prayer of Healing by 25%."] = "使你的治療禱言造成極效治療效果的機率提高25%。",
  ["Increases your chance to block attacks with a shield by 2%."] = "使你用盾牌格擋攻擊的機率提高2%。",
  ["Increases your chance to dodge an attack by 1%."] = "使你閃躲攻擊的機率提高1%。",
  ["Increases your chance to parry an attack by 1%."] = "使你招架攻擊的機率提高1%。",
  ["Increases your damage against undead by 2%."] = "使你對不死生物的傷害提高2%。",
  ["Increases your maximum Energy by 10."] = "使你的能量上限提高10點。",
  ["Increases your movement speed by 15% while in Bear, Cat, or Travel Form.  Only active outdoors."] = "使你在熊形態、獵豹形態或旅行形態下的移動速度提高15%，只能在戶外使用。",
  ["Increases your pet's chance to Dodge by 50% and decreases the time between your pet's attacks by 30%. Lasts 12 sec."] = "使你的寵物閃躲機率提高50%，攻擊間隔縮短30%。持續12秒。",
  ["Increases your pet's damage by 3%."] = "使你寵物所造成的傷害提高3%。",
  ["Increases your pet's stamina by 30 and all spell resistances by 40."] = "使你的寵物的耐力提高30點，所有法術抗性提高40點。",
  ["Increases your pet's stamina by 40 and all spell resistances by 60."] = "使你的寵物的耐力提高40點，所有法術抗性提高60點。",
  ["Indoctrinated Choker"] = "傳教頸圈",
  ["Inert Enchanting Rods"] = "無效的附魔棒",
  ["Infiltrate Krol'dok Stronghold and return to Commander Brant with proof of their leader's demise."] = "潛入克羅多克要塞，並帶著他們領袖死亡的證明回去找指揮官布蘭特。",
  ["Infiltrate Krol'dok Stronghold and return to Krom'rosh with proof of their leader's demise."] = "潛入克羅多克要塞，並帶著他們領袖死亡的證明回去找克隆羅許。",
  ["Inflicts 10 Nature damage over 10 sec. Effect can stack up to 5 times on a single target."] = "在10秒內造成總計10點自然傷害。單一目標身上的效果最多可疊加5次。",
  ["Inflicts 20 Nature damage over 10 sec. Effect can stack up to 5 times on a single target."] = "在10秒內造成總計20點自然傷害。單一目標身上的效果最多可疊加5次。",
  ["Inflicts 25 Nature damage over 10 sec. Effect can stack up to 5 times on a single target."] = "在10秒內造成總計25點自然傷害。單一目標身上的效果最多可疊加5次。",
  ["Inflicts 5 Nature damage over 10 sec. Effect can stack up to 5 times on a single target."] = "在10秒內造成總計5點自然傷害。單一目標身上的效果最多可疊加5次。",
  ["Inflicts 60 to 66 additional Holy damage on the target of a Paladin's Judgement."] = "對聖騎士審判的目標額外造成60到66點神聖傷害。",
  ["Inflicts Nature damage over 10 sec. Effect can stack up to 5 times on a single target."] = "在10秒內造成自然傷害。效果可在同一目標上疊加最多5次。",
  ["Info bar"] = "資訊列",
  ["Infurnus"] = "因弗納斯",
  ["Inject the Hissing Serum into the system above Othmar's body for Master Apothecary Faranell."] = "幫大藥劑師法拉尼爾把嘶鳴藥水注射到歐斯瑪遺骸上的系統管道中。",
  ["Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine."] = "將臟兮兮的東西放入超級清潔器5200型，記得要用三枚銀幣來啟動機器。",
  ["Inside Blackrock Depths"] = "在黑石深淵裡",
  ["Inside Dire Maul East"] = "在厄運之槌東區裡",
  ["Inside Gnomeregan"] = "在諾姆瑞根裡",
  ["Inside Stratholme"] = "在斯坦索姆裡",
  ["Inside a dungeon that has a map, the world map key (M) opens OneForAll's dungeon map instead of the world map. Press it again to close. Takes effect outside combat."] = "在有地圖的地城裡，世界地圖按鍵（M）會打開 OneForAll 的地城地圖，而不是世界地圖。再按一次關閉。脫離戰鬥後生效。",
  ["Inside a dungeon, M opens OneForAll's dungeon map."] = "在地城裡，按 M 打開 OneForAll 的地城地圖。",
  ["Inside a hut; the climb starts roughly around 31.0, 37.0."] = "在一間小屋裡；大約從 31.0, 37.0 附近開始往上爬。",
  ["Inside a tower in the ogre ruins."] = "在巨魔廢墟的一座塔裡。",
  ["Inside the Thelsamar inn. Alternative location: Westfall, Sentinel Hill 52.7, 53.8."] = "在塞爾薩瑪的旅店裡。另一個位置：西部荒野，哨兵嶺 52.7, 53.8。",
  ["Inside the Timbermaw tunnel between Felwood and Winterspring."] = "在費伍德森林和冬泉谷之間的木喉隧道裡。",
  ["Inside the crypt on the south side; approach is roughly around 56.0, 45.0."] = "在南側的墓穴裡；入口大約在 56.0, 45.0 附近。",
  ["Inside the farmhouse."] = "在農舍裡。",
  ["Inside the oil platform control room."] = "在採油平台的控制室裡。",
  ["Inside the town hall."] = "在鎮公所裡。",
  ["Instant Poison III"] = "速效毒藥 III",
  ["Instead of item by item."] = "而不是一件一件拿。",
  ["Instead of only what it holds; the game shows \"*\" for more than 999. On by default for hunters."] = "不是只算箭袋裡裝的；超過 999 時遊戲會顯示「*」。獵人預設開啟。",
