  ["Inventory is full."] = "物品欄已滿。",
  ["Investigate Fenris Isle to the east and learn the fate of the Earthen Ring traveling party."] = "調查東邊的芬里斯島，查明陶土議會旅行隊伍的下落。",
  ["Investigate Fenris Keep to the north and attempt to locate the missing member of the Earthen Ring party."] = "調查北邊的芬里斯城堡，試著找到陶土議會隊伍中失蹤的成員。",
  ["Investigate the Forlorn Gardens near Shen'dralas and then return to Mithera at the nearby temple."] = "調查申德拉斯附近的淒涼花園，然後回到附近神殿的米瑟菈那裡。",
  ["Invites players who whisper you the keyword."] = "邀請用密語對你說出關鍵字的玩家。",
  ["Iron-Wrought Cuffs"] = "鐵鑄腕甲",
  ["It Must Be Destroyed"] = "必須摧毀它",
  ["It sits above the chat menu button. Also as a key: Key Bindings > OneForAll > Hide / show chat. Pressing Enter to type brings the chat back."] = "它位在聊天選單按鈕上方。也可設定按鍵：按鍵設定 > OneForAll > 隱藏／顯示聊天。按 Enter 打字時聊天會重新出現。",
  ["It will not be suggested again (any character)."] = "之後不會再建議它（所有角色）。",
