  ["Kill 12 Fen Creepers, then return to Rethiel the Greenwarden in the Wetlands."] = "殺死12隻沼澤爬行者，然後向濕地的綠色守衛者雷希耶爾覆命。",
  ["Kill 15 Kurzen Jungle Fighters.  Return to Sergeant Yohwa at the Rebel Camp."] = "殺死15名庫爾森叢林戰士，然後向反抗軍營地的尤瓦中士覆命。",
  ["Kill 15 Mosshide Gnolls and 10 Mosshide Mongrels, then return to Rethiel the Greenwarden in the Wetlands."] = "殺死15名蘚皮豺狼人和10名混血蘚皮豺狼人，然後向濕地的綠色守衛者雷希耶爾覆命。",
  ["Kill 5 Empowered Brutes and 10 Twilight Ritualists then return to Clubtoe in Sunnyglade."] = "殺死5個強化蠻卒和10個暮光祭儀師，之後回到陽光林地找棒趾。",
  ["Kill 6 Dalaran Summoners and 12 Elemental Slaves, then return to Magus Voidglare in Tarren Mill."] = "殺掉6個達拉然召喚師和12個元素奴僕，然後回到塔倫米爾去見大法師沃迪恩·伍德格萊爾。",
  ["Kill 7 Twilight Maulers and 7 Twilight Firecallers for Clugfist in Bolder'ok."] = "幫博德羅克的鈍拳殺死7個暮光虐待者和7個暮光召火者。",
  ["Kill 8 Bleeding Horrors and 8 Wandering Spirits, then report back to Linnea at her camp."] = "殺死8個可怕的血僵屍和8個遊蕩的幽靈，然後向亡靈衛兵林奈匯報。",
  ["Kill Chogg'Zac in the Sunnyglade cave and collect their heads for Clubtoe."] = "在陽光林地的洞穴殺死喬札克，把他們的頭顱拿給棒趾。",
  ["Kill Nar'gurk within Krol'dok Stronghold and recover any valuable information."] = "在克羅多克要塞內殺死納古克，並取回任何重要情報。",
  ["Kill a Highland Horror within Excavation Sites and bring its root core to Rethiel the Greenwarden in the Wetlands."] = "在挖掘場殺死一隻高地恐獸，把牠的根核帶給濕地的綠色守衛者雷希爾。",
  ["Kill the troll minibosses on the balcony around the circle of statues; then the statues can be activated in order."] = "殺死雕像圓環周圍陽台上的食人妖小首領；之後就能依序啟動雕像。",
