  ["Long \"Equip:\" lines in tooltips as short stats, e.g. \"+1% Hit\"."] = "把提示框中很長的「裝備：」文字改成精簡屬性，例如「+1% 命中」。",
  ["Longwalker Malah"] = "遠行者瑪拉",
  ["Look for King Varian Wrynn in Alcaz Prison."] = "在奧卡茲監獄尋找瓦里安·烏瑞恩國王。",
  ["Look underwater in the Pool of Ask'ar: a Pitted Iron Chest in the north niche behind Ghamoo-ra holds the manuscript."] = "在阿斯卡之池的水底找：加摩拉後方北側凹處的一個坑窪鐵箱裡有手稿。",
  ["Looking for Group"] = "尋求組隊",
  ["Looks for spells on your action bars that use a lower rank than one you already know, and offers to put the highest rank there. After a trainer visit it waits until you close the trainer window. Macros are not checked."] = "找出快捷列上等級比你已學會的還低的法術，並提議換成最高等級。拜訪訓練師後會等你關閉訓練師視窗才檢查。不檢查巨集。",
  ["Loot"] = "掉落",
  ["Loot & Vendors"] = "拾取與商人",
  ["Loot The Scarlet Key from the strongbox behind Arcanist Doan. It stays in your keyring."] = "從祕法師杜安後面的保險箱拾取血色十字軍鑰匙。它會放在你的鑰匙圈裡。",
  ["Loot a Waylaid Crate while questing (system starts around level 10)."] = "做任務時拾取遭攔截的木箱（這個系統大約從 10 級開始）。",
  ["Loot feed"] = "拾取提示",
  ["Loot for this new Forever dungeon has not been recorded yet. It will be added once drop data is available."] = "這個永恆新地城的戰利品還沒有記錄。有掉落資料後會再加上。",
  ["Loot it again after making room."] = "騰出空間後再拾取一次。",
  ["Loot the Grimy Key from a Warden's Footlocker upstairs in a house of the Lordamere Internment Camp (guarded by Warden Belamoore) and bring it to Magus Wordeen Voidglare in Tarren Mill."] = "從洛丹米爾拘留營一棟房子二樓的典獄官的櫃子裡拿到骯髒的鑰匙（由典獄官貝拉摩爾看守），交給塔倫米爾的魔導師沃迪恩‧虛無之光。",
  ["Looted items and money float up next to your character."] = "拾取的物品和金錢會在你的角色旁邊往上飄。",
