  ["Neck"] = "頸部",
  ["Need"] = "需要",
  ["Needed to enter"] = "進入需要",
  ["Needed to enter Onyxia's Lair. Each faction earns it at the end of a long quest chain that starts around level 50 (Alliance) or 55 (Horde) and leads through Blackrock Spire."] = "進入奧妮克希亞的巢穴需要它。各陣營要完成一長串任務系列才能取得，從約 50 級（聯盟）或 55 級（部落）開始，一路經過黑石塔。",
  ["Needs Auctionator (the prices come from it); without it the line stays away. Green, blue and purple weapons and armor: the dust, essences and shards it usually gives, from the known disenchant chances by quality and item level - an estimate."] = "需要 Auctionator（價格從它來）；沒有它這行不會出現。綠色、藍色、紫色的武器和護甲：依品質和物品等級的已知分解機率，算出它通常會給的粉、精華和碎片——是估計值。",
  ["Needs Auctionator: the auction house prices come from it."] = "需要 Auctionator：拍賣場價格從它來。",
  ["Needs Bazil Thredd first, which starts with An Unsent Letter from Edwin VanCleef."] = "需要先完成「巴基爾·斯瑞德」，它從艾德溫·范克里夫的「未寄出的信」開始。",
  ["Needs Chief Engineer Scooty (from Sovik in Orgrimmar). With the Goblin Transponder you can use Scooty's teleporter in Booty Bay to get to Gnomeregan."] = "需要總工程師斯庫提（奧格瑞瑪的索維克給的任務）。有了地精轉發器，就能用藏寶海灣斯庫提的傳送器到諾姆瑞根。",
  ["Needs Chief Engineer Scooty (from Sovik in Orgrimmar). With the Goblin Transponder you can use the teleporter in Gnomeregan to get back to Booty Bay."] = "需要先完成「主工程師斯庫提」（奧格瑪的索維克給的）。有了哥布林傳送器，就能用諾姆瑞根的傳送器回到藏寶海灣。",
  ["Needs Going, Going, Guano! from Razorfen Kraul. Hearts of Zeal drop from Scarlet enemies in every wing."] = "需要先完成剃刀沼澤的「鳥糞危機」。狂熱之心會從每個區域的血色敵人身上掉落。",
  ["Needs a tribute run: kill King Gordok with the guards still alive."] = "需要貢品路線：在守衛都還活著的情況下殺死戈多克大王。",
  ["Needs the Barrens oasis chain: The Barrens Oases, The Forgotten Pools, The Stagnant Oasis, Altered Beings, then Hamuul Runetotem and Nara Wildmane."] = "需要先完成貧瘠之地的綠洲系列：貧瘠之地的綠洲、遺忘之池、死水綠洲、變異的生物，然後是哈繆爾·符文圖騰和納拉·蠻鬃。",
  ["Nekrum Gutchewer joins the fight on the temple stairs, after Sergeant Bly's group frees the prisoners."] = "布萊中士的隊伍救出囚犯後，耐克魯姆會加入神廟階梯上的戰鬥。",
  ["Netherflame"] = "虛空之焰",
  ["Netherfroth"] = "虛空之沫",
  ["Nethergeld"] = "虛空之金",
  ["Netherlight"] = "虛空之光",
  ["Netherpearl"] = "虛空珍珠",
  ["Nethershine"] = "虛空光輝",
  ["Neutral"] = "中立",
  ["Never"] = "永不",
  ["Never Saddle on Quality"] = "鞍具品質絕不馬虎",
  ["Never suggest this item"] = "不再建議這個物品",
  ["Never suggested"] = "不再建議",
  ["New"] = "新增",
  ["New Forever dungeon: I'lalai, a lost troll city that has risen from the sea. Naga, risen trolls and stranded pirates fight over its ruins. Its loot is still being discovered: what players have recorded so far is listed."] = "永恆新地城：伊拉萊，一座從海裡升起的失落食人妖城市。納迦、復生的食人妖和受困的海盜在廢墟裡互相爭奪。掉落物還在探索中：列出的是玩家目前記錄到的。",
  ["New Forever dungeon: I'lalai, a lost troll city that has risen from the sea. Naga, risen trolls and stranded pirates fight over its ruins. Not open on the beta yet; bosses and loot can still change."] = "永恆新地城：伊拉萊，一座從海中浮起的失落食人妖城市。納迦、復生的食人妖和擱淺的海盜在廢墟中爭奪。測試版尚未開放；首領和戰利品仍可能變動。",
  ["New Forever dungeon: a Defias prison on Alcaz Island where nobles were held for ransom, and rumour says Varian Wrynn was one of them. Now the Defias fight the naga inside. Its loot is still being discovered."] = "永恆新地城：阿卡茲島上一座迪菲亞監獄，從前關著被拿來勒索贖金的貴族，傳說瓦里安·烏瑞恩也曾是其中之一。現在迪菲亞在裡面跟納迦作戰。掉落物還在探索中。",
  ["New Forever dungeon: a Defias prison on Alcaz Island where nobles were held for ransom, and rumour says Varian Wrynn was one of them. Now the Defias fight the naga inside. Not open on the beta yet; bosses, quests and loot are not known."] = "永恆新地城：奧卡茲島上的迪菲亞監獄，曾關押等著被勒索贖金的貴族，傳說瓦里安·烏瑞恩也是其中之一。現在迪菲亞正在裡面和納迦作戰。測試版尚未開放；首領、任務和戰利品都還不知道。",
  ["New Forever dungeon: a Twilight's Hammer ogre fortress on a hill in the Riverglades. The ogres raid nearby settlements and take prisoners. Its loot is still being discovered."] = "永恆新地城：大河林地一座山丘上的暮光之錘食人魔要塞。食人魔會襲擊附近的聚落、抓走俘虜。掉落物還在探索中。",
  ["New Forever dungeon: a Twilight's Hammer ogre fortress on a hill in the Riverglades. The ogres raid nearby settlements and take prisoners. Not open on the beta yet; bosses, quests and loot are not known."] = "永恆新地城：大河林地山丘上的一座暮光之錘食人魔要塞。食人魔襲擊附近的聚落並抓走俘虜。測試版尚未開放；首領、任務和戰利品都還不知道。",
  ["New Forever dungeon: a great furbolg city behind the gates of northern Azshara, whose people fight the corruption spreading through it. Its tunnels lead toward the Barrow Deeps raid. Its loot is still being discovered."] = "永恆新地城：艾薩拉北方大門後面一座巨大的熊怪城市，裡面的族人正在對抗蔓延全城的腐化。它的通道通往團隊副本「巴羅深淵」。掉落物還在探索中。",
  ["New Forever dungeon: a great furbolg city behind the gates of northern Azshara, whose people fight the corruption spreading through it. Its tunnels lead toward the Barrow Deeps raid. Not open on the beta yet; bosses, quests and loot are not known."] = "永恆新地城：艾薩拉北部大門後一座巨大的熊怪城市，城裡的居民正在對抗蔓延的腐化。它的隧道通往墓穴獸穴團隊副本。測試版尚未開放；首領、任務和戰利品都還不知道。",
  ["New Forever dungeon: titan terraces, power crystals and ancient wildlife in the hills of Un'Goro Crater. Its loot is still being discovered."] = "永恆新地城：安戈洛環形山丘陵間的泰坦平臺、能量水晶和遠古野生動物。掉落物還在探索中。",
  ["New Forever dungeon: titan terraces, power crystals and ancient wildlife in the hills of Un'Goro Crater. Not open on the beta yet; bosses, quests and loot are not known."] = "永恆新地城：安戈洛環形山丘陵中的泰坦平台、能量水晶和遠古生物。測試版尚未開放；首領、任務和戰利品都還不知道。",
  ["New Forever raid for 10 players, opening on 9 December 2026: the barrow dens where the night elves keep their most dangerous prisoners, now touched by spreading corruption. One of its entrances lies on Mount Hyjal. Loot and quests are not known yet."] = "永恆新的 10 人團隊副本，2026 年 12 月 9 日開放：夜精靈關押最危險囚犯的墓穴獸穴，如今受到蔓延的腐化侵蝕。其中一個入口位於海加爾山。戰利品和任務還不知道。",
  ["New Forever raid for 20 players, opening on 9 December 2026: snowy peaks, ancient elven ruins and ghosts of the Third War. Something drains the power of the land around the summit. Loot and quests are not known yet."] = "永恆新的 20 人團隊副本，2026 年 12 月 9 日開放：積雪的山峰、古老的精靈遺跡和第三次大戰的亡魂。有東西正在吸取山頂周圍大地的力量。戰利品和任務還不知道。",
  ["New in Forever"] = "永恆新內容",
  ["New in OneForAll"] = "OneForAll 新功能",
