  ["New in OneForAll 6.1.4: back to the world map."] = "OneForAll 6.1.4 新功能：回到世界地圖。",
  ["New in OneForAll 6.1.5: click a reagent to see where to get it - vendors, herbs and ore, mobs that drop it, with a map button."] = "OneForAll 6.1.5 新功能：點材料可查看哪裡取得——商人、草藥和礦、會掉落的怪物，並附地圖按鈕。",
  ["New in WoW Forever: no beast that teaches this ability is known yet."] = "魔獸世界：永恆新內容：還不知道有哪隻野獸會教這個技能。",
