  ["Obtain a Necrotic Runestone from Maleki the Pallid in Stratholme, then find the Rotting Dwarf Corpse near the Undercroft in southwestern Eastern Plaguelands."] = "從斯坦索姆的蒼白的瑪勒基身上取得亡域符文石，然後到東瘟疫之地西南方的墓室附近找到腐爛的矮人屍體。",
