  ["Old Lion Statue"] = "古老的獅子雕像",
  ["Old OneForAll channels left."] = "已離開舊的 OneForAll 頻道。",
  ["On Greater Heal critical hits, your target will gain Armor of Faith, absorbing up to 500 damage."] = "在強效治療術造成極效治療後，目標將獲得一面可吸收500點傷害的護盾。",
  ["On Healing Touch critical hits, you regain 30% of the mana cost of the spell."] = "當治療之觸產生極效治療效果後，獲得30%施放治療之觸所需的法力。",
  ["On a bench inside the large building."] = "在大型建築裡的長椅上。",
  ["On a bookshelf inside a pirate building."] = "在一棟海盜建築裡的書架上。",
  ["On a crate next to a hut."] = "在一間小屋旁的木箱上。",
  ["On a shelf behind the alchemy vendor."] = "在鍊金術商人後面的架子上。",
  ["On a shelf next to Apothecary Johaan."] = "在藥劑師喬漢旁邊的架子上。",
  ["On a table in the middle of the hall."] = "在大廳中央的桌上。",
  ["On a table in the ruined building above Scholomance."] = "在通靈學院上方廢墟建築裡的桌上。",
  ["On a table partway up the tower."] = "在塔的半途一張桌子上。",
  ["On each card: quiet until you cast it again."] = "每張卡片上：在你再施放一次之前保持安靜。",
  ["On gear you can use: how much better (green) or worse (red) it is than what you wear, weighted for your talent spec like Armory > Gear Planner. Also a green arrow on upgrades in your bags, the loot roll window and quest rewards, and a gold star for wishlist items (/ofa rolltest shows an example)."] = "對你能用的裝備：顯示它比你身上穿的好多少（綠色）或差多少（紅色），依你的天賦專精加權，跟「軍械庫 > 裝備規劃器」一樣。背包、戰利品擲骰視窗和任務獎勵中的升級物品也會出現綠色箭頭，願望清單物品會有金色星星（/ofa rolltest 可看範例）。",
  ["On the altar inside the tomb; no dungeon entry required. Coordinates use the Burning Steppes map."] = "在墓穴裡的祭壇上；不需要進入地城。座標使用燃燒平原的地圖。",
  ["On the ground on the eastern edge of the murloc camp."] = "在魚人營地東側邊緣的地上。",
  ["On top of the temple, outside the instance; player-reported location."] = "在神廟頂上、副本外面；位置為玩家回報。",
  ["On your junk list"] = "在你的垃圾清單上",
  ["One Shot.  One Kill."] = "一擊必殺",
  ["One complete bundle is enough to seal a crate. Beta values can still change."] = "一整份完整的材料包就能封好一個木箱。測試版的數值仍可能變動。",
  ["One of the Lost Dwarves, together with Eric \"The Swift\" and Olaf."] = "失落的矮人之一，和「迅捷者」埃瑞克以及奧拉夫一起。",
  ["One of the Seven, the Dark Iron spirits fought in turn before Doom'rel."] = "七賢之一，在杜姆雷爾之前輪流迎戰的黑鐵靈魂。",
  ["One-Hand"] = "單手",
  ["One-time introductory reward reported by testers."] = "測試者回報的一次性入門獎勵。",
  ["OneForAll Profit"] = "OneForAll 利潤",
