  ["OneForAll marker"] = "OneForAll 標記",
  ["OneForAll no longer moves the minimap itself: it fought with the Edit Mode, the minimap jumped back and could not be moved any more."] = "OneForAll 不再自己移動小地圖了：它跟編輯模式打架，小地圖會跳回去、之後也移不動。",
  ["OneForAll no longer uses a chat channel: the game blocks channels with many players. Recipes are shared in your guild."] = "OneForAll 不再使用聊天頻道：遊戲會封鎖人數很多的頻道。配方改在你的公會內分享。",
  ["OneForAll no longer uses chat channels (the game blocks them). You can leave them:"] = "OneForAll 不再使用聊天頻道（遊戲會封鎖它們）。你可以離開這些頻道：",
