  ["Only during the Scourge Invasion event."] = "只在天譴入侵活動期間。",
  ["Only for Herbalism and Mining: the herb or ore vein near you sparkles."] = "只限草藥學和採礦：你附近的草藥或礦脈會閃光。",
  ["Only for professions you have. Uses the game's soft targeting (interaction target): one object at a time, the nearest one around you. Vendors and other NPCs get no sparkle. Works only close up (about 15 yards) - a limit of the game. Switching it on turns on the game's \"Enable Interact Key\" and its interact icons on objects - both are needed to find the nodes; if you switch them off later, nothing sparkles. Whether icons show above nodes and NPCs is up to you (game setting \"Interact Key Icons\"). Everything goes back when you switch this off. Not with a controller. Idea and sparkle from the addon Lueur (MIT)."] = "只對你有的專業技能有效。使用遊戲的軟目標（互動目標）：一次一個物件，選你周圍最近的那個。商人和其他 NPC 不會閃光。只在很近的距離有效（約 15 碼）——這是遊戲的限制。打開時會一起打開遊戲的「啟用互動鍵」和物件上的互動圖示——兩個都要開才找得到採集點；之後如果你把它們關掉，就不會閃光。採集點和 NPC 頭上要不要顯示圖示由你決定（遊戲設定「互動鍵圖示」）。關掉這個功能時全部會還原。不支援遊戲手把。點子和閃光效果來自插件 Lueur（MIT）。",
  ["Only for professions you have. Uses the game's soft targeting (interaction target): one object at a time, the nearest one around you. Vendors and other NPCs get nothing. Works only close up (about 15 yards) - a limit of the game. Changes a few game settings and gives them back when you switch this off. Idea and sparkle from the addon Lueur (MIT)."] = "只對你有的專業技能有效。使用遊戲的軟目標（互動目標）：一次一個物件，選你周圍最近的那個。商人和其他 NPC 不受影響。只在很近的距離有效（約 15 碼）——這是遊戲的限制。會改變幾個遊戲設定，關閉這個功能時會還原。點子和閃光效果來自插件 Lueur（MIT）。",
  ["Only grey and white items"] = "只限灰色和白色物品",
  ["Only guild members who also use OneForAll and have this switched on. Switched off, your position is not sent any more and you see nobody else either. Inside a dungeon or raid only which one is sent: a green guild flag on its entrance, the names in its tooltip. Members in your group are left out, the game shows them already. Also on the continent map, a little smaller. Guild members who share their position with the addon OpenMap are shown too."] = "只限也用 OneForAll、而且有打開這個功能的公會成員。關掉之後就不會再送出你的位置，你也看不到其他人。在地城或團隊副本裡只會送出是哪一個副本：入口上一面綠色公會旗，名字在它的滑鼠提示裡。跟你同隊伍的成員不會顯示，遊戲本來就會顯示他們。大陸地圖上也有，小一點。用 OpenMap 插件分享位置的公會成員也會顯示。",
  ["Only items better than what you wear (for your spec) are listed."] = "只會列出比你身上裝備更好的物品（依你的專精）。",
  ["Only known recipes"] = "只看已學會的配方",
  ["Only quests you can take now: your level (no grey ones, none too high), your side and class, pre-quests done. Hover an icon for the quests and their levels. Hidden while Questie is loaded, it shows its own. Quest data from QuestieDB (GPL); the new Forever zones are not in it yet."] = "只顯示你現在能接的任務：符合你的等級（沒有灰色的、也沒有太高的）、你的陣營和職業、前置任務已完成。滑鼠移到圖示上可看任務和等級。載入 Questie 時會隱藏，改用 Questie 自己的。任務資料來自 QuestieDB（GPL）；永恆新區域還沒有收錄。",
  ["Only quests your group members are missing and can take."] = "只分享你的隊友缺少而且能接的任務。",
  ["Only sold by"] = "只有以下商人販售：",
  ["Only tameable lavender saber cat."] = "唯一可馴服的淡紫色劍齒豹。",
  ["Only the icon with the time left on it."] = "只顯示圖示，上面標著剩餘時間。",
  ["Only tracked quests"] = "只算追蹤中的任務",
  ["Only when not pinned."] = "只在沒有釘住時。",
  ["Only while a card is shown."] = "只在卡片顯示時。",
  ["Only your bags and bank count; what your other characters have is bought or farmed like everything else."] = "只算你的背包和銀行；其他角色有的，會跟其他東西一樣算成要買或要自己打。",
  ["Opacity"] = "透明度",
  ["Open"] = "開啟",
  ["Open / close"] = "開啟／關閉",
  ["Open Beast Training once so OneForAll knows your ranks"] = "先打開一次「野獸訓練」，OneForAll 才知道你的等級",
  ["Open Doan's Strongbox"] = "打開杜安的保險箱",
  ["Open Map"] = "打開地圖",
  ["Open OneForAll from the game's AddOns list at the minimap or with /ofa. Not together with \"Collect minimap buttons\": the bar needs its button."] = "從小地圖的遊戲「插件」清單，或用 /ofa 打開 OneForAll。不能和「收集小地圖按鈕」同時使用：按鈕列需要它的按鈕。",
  ["Open Professions"] = "打開專業技能",
  ["Open Profit"] = "打開利潤",
  ["Open Quality of Life"] = "打開生活便利",
  ["Open Skill-Up Helper"] = "打開練技能助手",
  ["Open a recipe in Professions and click \"+ List\"."] = "在「專業技能」中打開一個配方，然後點「+ 清單」。",
  ["Open automatically"] = "自動打開",
  ["Open flight map at once"] = "立刻打開飛行地圖",
  ["Open guide"] = "打開指南",
  ["Open the auction house and buy:"] = "打開拍賣場，買：",
  ["Open the auction house, send the shopping list to Auctionator and buy everything on it."] = "打開拍賣場，把購物清單送到 Auctionator，買清單上的全部。",
  ["Open the dungeon and pick the Key tab for the steps."] = "打開地城並選「鑰匙」分頁查看步驟。",
  ["Open the list to allow single items again, or remove all."] = "打開清單可重新允許個別物品，或全部移除。",
  ["Open the quest in Dungeons & Raids."] = "在「地城與團隊」裡打開這個任務。",
  ["Open the raid and pick the Attunement tab for the steps."] = "打開團隊副本並選「進入資格」分頁查看步驟。",
  ["Open the recipe in Professions."] = "在「專業技能」中打開配方。",
  ["Open the world map (M) - the place is marked there."] = "打開世界地圖（M）——地點有標在上面。",
  ["Open the world map and mark this location with the golden OneForAll pin."] = "打開世界地圖，用金色的 OneForAll 標記標出這個位置。",
  ["Open the world map and mark this pickup location with the golden OneForAll pin."] = "打開世界地圖，用金色的 OneForAll 標記標出這個接任務的位置。",
  ["Open your"] = "打開你的",
  ["Open your class trainer first, then type /ofa trainer again."] = "請先打開你的職業訓練師，然後再輸入一次 /ofa trainer。",
  ["Opens 9 December"] = "12 月 9 日開放",
  ["Opens the Shadowforge gates in Blackrock Depths (a shortcut; without it the doors need a rogue or Seeping Flames)."] = "打開黑石深淵的暗爐城大門（捷徑；沒有它的話，門需要盜賊或滲出之焰才能打開）。",
  ["Opens the Workshop side entrance and doors inside Gnomeregan."] = "打開諾姆瑞根的工作坊側門入口和內部的門。",
  ["Opens the door to Upper Blackrock Spire. Collect the Unadorned Seal and three gemstones in Lower Blackrock Spire, then forge the seal at the dragon in Dustwallow Marsh."] = "打開上層黑石塔的門。在下層黑石塔收集無瑕的印章和三顆寶石，然後到塵泥沼澤的巨龍那裡鍛造印章。",
  ["Opens the doors of Dire Maul West and North (also the Gordok side door). One key holder in the group is enough."] = "打開厄運之槌西區和北區的門（也包括戈多克側門）。隊伍中有一人持有鑰匙就夠了。",
  ["Opens the doors of the Armory and the Cathedral. Anyone in the group who has it can open them."] = "打開軍械庫和大教堂的門。隊伍中任何有它的人都能開門。",
  ["Opens the gate of Scholomance in Caer Darrow. Made by Krinkle Goodsteel in Gadgetzan from Imbued Skeletal Fragments; the last step is a quest for your faction."] = "打開凱爾達隆的通靈學院大門。由加基森的克林科·古德斯迪爾用灌魔骸骨碎片製作；最後一步是你陣營的任務。",
  ["Opens the gates between the two halves of Stratholme. Both gates can be entered without it."] = "打開斯坦索姆兩半之間的大門。沒有它也能進入兩邊的大門。",
  ["Opens the portal from the Maraudon entrance straight to Princess Theradras' falls."] = "打開從瑪拉頓入口直達瑟萊德絲公主瀑布的傳送門。",
  ["Opens the prison cells in the Detention Block (Jail Break!)."] = "打開監獄區的牢房（越獄！）。",
  ["Opens the sewer entrance into Dalaran by the Lordamere Lake. It comes with the quest Heart of Disruption from the Image of Archmage Modera; the Alliance gets there with one lead-in quest, the Horde with Magus Wordeen Voidglare's quests in Tarren Mill."] = "打開洛丹米爾湖邊通往達拉然的下水道入口。它跟著大法師莫德菈的影像給的任務「干擾之心」一起來；聯盟接一個引導任務就能到那裡，部落要做塔倫米爾的魔導師沃迪恩‧虛無之光的任務。",
  ["Opens the trainer window: spells and weapon skills."] = "打開訓練師視窗：法術和武器技能。",
  ["Opens the way to Molten Core: the Core Fragment lies at the Molten Core portal in Blackrock Depths."] = "開啟通往熔火之心的路：熔火之心碎片在黑石深淵的熔火之心傳送門處。",
  ["Opens when a group member can still accept one of your dungeon quests."] = "有隊伍成員還能接你的地城任務時自動打開。",
  ["Opens your profession window if it is closed; click again to craft the amount on the left."] = "如果專業技能視窗沒開會先打開；再點一次就製作左邊的數量。",
  ["Opens your profession window if it is closed; click again to craft."] = "如果專業技能視窗沒開會先打開；再點一次就製作。",
  ["Optional"] = "可選",
  ["Optional lead-in for Open the Maw."] = "「開啟巨口」的可選前導任務。",
  ["Optional lead-in: Castpipe's Task, from Gaxim Rustfizzle in Stonetalon Mountains."] = "可選的前導任務：石爪山脈加克希姆·塵鏈給的「卡斯派普的任務」。",
  ["Optional lead-in: Klockmort's Essentials, from Mathiel in Darnassus."] = "可選的前導任務：達納蘇斯瑪希爾給的「幫助科勞莫特」。",
  ["Optional lead-in: Tinkmaster Overspark, from Brother Sarno in Stormwind."] = "可選的前導任務：暴風城薩爾努修士給的「工匠大師歐沃斯巴克」。",
  ["Optional lead-in: Trouble in the Deeps from Tsunaman in Stonetalon Mountains. Je'neu Sancrea also gives it directly."] = "可選的前導任務：石爪山脈的蘇納曼給的「幫助耶努薩克雷」。耶努薩克雷也會直接給這個任務。",
  ["Optional lead-in: not required to accept the quest."] = "可選的前導任務：接這個任務時不是必要的。",
  ["Optional shortcut"] = "可選的捷徑",
  ["Optional: the Fathom Stone also lets you summon Baron Aquanis."] = "可選：深淵之石也能讓你召喚阿奎尼斯男爵。",
  ["Optional; leads to Lost in the Thicket Things."] = "可選；後續是「迷失在灌木叢中」。",
  ["Options are saved in the profile this character uses (see Profiles)."] = "選項會存在這個角色使用的設定檔中（見「設定檔」）。",
  ["Orphan Matron Aria"] = "孤兒監護員艾瑞雅",
  ["Ortak Lomgok"] = "歐塔克·隆戈克",
  ["Orthas"] = "歐薩斯",
  ["Other OneForAll users online who know it"] = "在線且會這個配方的其他 OneForAll 使用者",
  ["Other Sets"] = "其他套裝",
  ["Other players may send you their profile. You are always asked before it is saved. When off, they get a note that you turned it off."] = "其他玩家可以傳他們的設定檔給你。儲存之前一定會先問你。關閉時，對方會收到你已關閉的通知。",
  ["Other users"] = "其他使用者",
  ["Other users ("] = "其他使用者（",
  ["Others"] = "其他",
  ["Our Ancient Enemy"] = "我們的遠古之敵",
  ["Our Man in Theramore"] = "塞拉摩的眼線",
  ["Outrider's Gloves"] = "先遣騎手套",
  ["Outside the mine on a platform."] = "在礦坑外的平台上。",
  ["Overgrown Cuffs"] = "過度生長腕輪",
  ["Overlord Mugg"] = "魔王莫格",
  ["Overseer Mugg"] = "監工莫格",
  ["Overseer Wrex"] = "監工雷克斯",
  ["Overview"] = "總覽",
  ["PET ABILITY NEARBY"] = "附近有寵物技能",
  ["Paige"] = "佩姬",
  ["Paladin weapon quest across Deadmines"] = "橫跨死亡礦坑的聖騎士武器任務",
  ["Panic at the Digsite"] = "挖掘場恐慌",
  ["Parry"] = "招架",
  ["Parry (per 1 %)"] = "招架（每 1 %）",
  ["Part 1 of 2. Finishing it at Maur's body gives you Returning the Lost Satchel."] = "第 1／2 部分。在莫爾的屍體處完成後，會得到「歸還背包」。",
  ["Part 1 of 5. At the end of the chain you pick Monstrous Cleaver, Grave Shroud or Slain Baron's Signet."] = "第 1／5 部分。系列最後可以從巨型切肉刀、墓穴裹屍布或被殺男爵的印戒中選一件。",
  ["Part 2 of 2. Starts from the Grimtotem Satchel in the dungeon."] = "第 2／2 部分。從地城裡的恐怖圖騰背包開始。",
  ["Part of the Onyxia attunement (Alliance)."] = "奧妮克希亞進入資格的一部分（聯盟）。",
  ["Part of the Onyxia attunement (Horde)."] = "奧妮克希亞進入資格的一部分（部落）。",
  ["Partial data"] = "部分資料",
  ["Passing the Blame"] = "推卸責任",
  ["Paste a build link of talentsforever.com or wowforevertalents.com, or an OneForAll build string (Ctrl+V)."] = "貼上 talentsforever.com 或 wowforevertalents.com 的配點連結，或 OneForAll 的配點字串（Ctrl+V）。",
  ["Paste a build link of talentsforever.com or wowforevertalents.com, or an OneForAll build string."] = "貼上 talentsforever.com 或 wowforevertalents.com 的配點連結，或 OneForAll 的配點字串。",
  ["Paste a profile text (Ctrl+V). It is saved as a new profile."] = "貼上設定檔文字（Ctrl+V）。會存成一個新的設定檔。",
  ["Paste a profile text; it is saved as a new profile."] = "貼上設定檔文字；會存成新的設定檔。",
  ["Paste your build link here when it is done."] = "配好之後，把天賦配點連結貼到這裡。",
  ["Patricia Egan"] = "派翠西亞·伊根",
  ["Pattern:"] = "圖樣：",
  ["Pattern: Blue Suede Shoulder"] = "圖樣：藍色麂皮護肩",
  ["Pattern: Charged Scorpid Shoulder"] = "圖樣：充能蠍子護肩",
  ["Pattern: Double-stitched Leather Gloves OLD"] = "圖樣：雙線皮手套（舊）",
  ["Pattern: Mender's Leather Shoulder"] = "圖樣：治癒者皮甲護肩",
  ["Pattern: Mender's Mail Shoulder"] = "圖樣：治癒者鎖甲護肩",
  ["Pattern: Prowler's Leather Shoulder"] = "圖樣：徘徊者皮甲護肩",
  ["Pattern: Skirmisher's Mail Shoulder"] = "圖樣：散兵鎖甲護肩",
  ["Pattern: Skycaller's Leather Shoulder"] = "圖樣：喚天者皮甲護肩",
  ["Pattern: Skycaller's Mail Shoulder"] = "圖樣：喚天者鎖甲護肩",
  ["Pattern: Stalker's Mail Shoulder"] = "圖樣：潛獵者鎖甲護肩",
  ["Pattern: Supple Scorpid Shoulder"] = "圖樣：柔韌蠍子護肩",
  ["Pattern: Warden's Leather Shoulder"] = "圖樣：守望者皮甲護肩",
  ["Pattern: Wicked Leather Shoulder"] = "圖樣：邪惡皮甲護肩",
  ["Patterns"] = "圖樣",
  ["Patterns from the auction house"] = "拍賣場的圖樣",
  ["Patterns from vendors"] = "商人的圖樣",
  ["Pauldrons of the Stone Guardian"] = "石頭守護者肩鎧",
  ["Peacekeeper Wand"] = "保安官魔杖",
  ["Pearly"] = "珍珠般的",
  ["Permanently enchants a melee weapon. When you are parried or dodged, heals you for 5% of your maximum health. Cannot occur more than once every 10 sec."] = "永久附魔一把近戰武器。你的攻擊被招架或閃躲時，為你恢復最大生命力的5%。每10秒最多觸發一次。",
  ["Permanently enchants a weapon with Revelation. After a direct spell fails to critically strike, Revelation can make your next spell much more likely to critically strike."] = "用揭露永久附魔一把武器。直接法術沒有造成致命一擊後，揭露能讓你的下一個法術更容易造成致命一擊。",
  ["Permanently enchants a weapon with a chance while casting to grant Insight, increasing Spirit by 100% for 10 sec."] = "永久附魔一把武器，施法時有一定機率獲得洞察，使精神提高100%，持續10秒。",
  ["Pet Trainer"] = "寵物訓練師",
  ["Pet ability alert"] = "寵物技能提醒",
  ["Pet ability alerts"] = "寵物技能提醒",
  ["Pet ability alerts paused for 15 minutes."] = "寵物技能提醒已暫停 15 分鐘。",
  ["Pet families, abilities with every rank and where to learn them, and notable rare tames."] = "寵物類別、每個等級的寵物技能和學習地點，以及值得馴服的稀有寵物。",
  ["Pet trainers of your faction"] = "你陣營的寵物訓練師",
  ["Pet training"] = "寵物訓練",
  ["Pets and Guardians"] = "寵物與守護者",
  ["Pexmit"] = "佩克斯米特",
  ["Physician"] = "醫師",
  ["Pick a profession to browse all of its recipes (where to learn them, reagents, who in your guild knows them) or the Merchant's Favor recipes. Camping Buffs lists the campsite objects of every profession."] = "選一個專業技能，瀏覽它所有的配方（在哪學、材料、公會裡誰會），或商人貢獻點配方。「紮營增益」列出每個專業技能的營地物件。",
  ["Pick a step on the left for its details and map position."] = "在左邊選一個步驟，查看詳細內容和地圖位置。",
  ["Pick one or more. Bind on Equip: items you can buy in the auction house. Crafted: your own professions with everything, other professions only Bind on Equip."] = "選一個或多個。裝備後綁定：可以在拍賣場買到的物品。製作：你自己的專業技能全部列出，其他專業技能只列裝備後綁定的。",
  ["Picked up in Darnassus. Leads on to Blackfathom Villainy."] = "在達納蘇斯接取。後續任務是「黑暗深淵中的惡魔」。",
  ["Pieces"] = "部件",
  ["Pinches an enemy's legs for damage and reduces movement speed by 50% for 9 sec."] = "箝住敵人的腿造成傷害，並使其移動速度降低50%，持續9秒。",
  ["Pinned (stays open)"] = "釘住（保持打開）",
  ["Pip Quickwit, At Your Service!"] = "皮普·捷思，為您效勞！",
  ["Place Dawn's Gambit in the Viewing Room, then defeat Vectus."] = "把黎明先鋒放在觀察室，然後擊敗維克圖斯。",
  ["Place the Blood of Innocents in the brazier on the porch to summon Kirtonos."] = "把無辜者之血放進門廊的火盆中來召喚基爾圖諾斯。",
  ["Plague Defiled Buckler"] = "瘟疫污染圓盾",
  ["Plain bright bars for the class colors."] = "職業顏色使用單純的明亮計量條。",
  ["Plan talents for every class. See your next spells to learn."] = "規劃每個職業的天賦。查看你接下來要學的法術。",
  ["Plan what to craft: the materials you have in your bags, bank and on your other characters, and what is still missing. Add recipes with \"+ List\". Also /ofa craft."] = "規劃要做什麼：你背包、銀行和其他角色身上已有的材料，以及還缺什麼。用「+ 清單」加入配方。也可以用 /ofa craft。",
  ["Planned"] = "已規劃",
  ["Plans this many and shows the materials you have and still need."] = "規劃這麼多個，並顯示你已有和還需要的材料。",
  ["Plans:"] = "設計圖：",
