  ["Puts your pet in stealth mode, but slows its movement speed by 50%. The first attack from stealth receives a 20% bonus to damage. Lasts until cancelled."] = "使你的寵物進入潛行模式，但其移動速度會降低50%。在潛行狀態下發動的第一次攻擊將對目標造成20%的額外傷害。潛行效果會一直持續，直到被取消。",
