  ["Recover shards and fragments of the pylons, found guarded at the Magram and Gelkis villages. Return them to Mordent Evenshade."] = "在瑪格拉姆和吉爾吉斯村落取回受到看守的水晶塔碎片。然後再把它們交給摩丹特‧平影。",
  ["Recover the Alcaz Shackle Key from The Questioner in Alcaz Prison."] = "在奧卡茲監獄從審問者手上取回奧卡茲鐐銬鑰匙。",
