  ["Reduces all damage your pet takes by 50% and increases the time between your pet's attacks by 60%, but deals more damage with each attack. Lasts 12 sec."] = "使你的寵物受到的所有傷害降低50%，並使你的寵物的攻擊間隔時間提高60%，但每次攻擊造成傷害提高。持續12秒。",
