  ["Reduces the cooldown of Rebirth by 10 minutes."] = "使復生的冷卻時間減少10分鐘。",
  ["Reduces the cooldown of your Aimed Shot and Multi-Shot abilities by 1 sec."] = "使你瞄準射擊和多重射擊技能的冷卻時間縮短1秒。",
