  ["Slay 12 Meadowsbrook Farmhands, then return to Krom'rosh with news of your success."] = "殺死12個草原溪地雇農，然後向克隆羅許回報成功的消息。",
  ["Slay 3 Saltseer Coroners and Captain Dreadrise in the Drowned City."] = "在沉沒之城殺死3個鹽占驗屍官和懼湧船長。",
  ["Slay 4 Kobold Diggers in the Jangolode Mine and 6 Riverpaw Miners in the Gold Coast Quarry."] = "在詹戈洛德礦坑殺死4個狗頭人挖掘者，並在金海岸礦坑殺死6個河爪礦工。",
  ["Slay 6 Ravasaur Matriarchs, 9 Ironhide Ravasaurs and Venomridge in Shaper's Terrace."] = "在塑造者殿堂殺死6隻暴掠龍族母、9隻鐵皮暴掠龍和毒脊。",
  ["Slay 8 Farholde Priests and 12 Farholde Scouts south of the river."] = "在南邊河畔殺死8個遠境堡牧師和12個遠境堡斥候。",
  ["Slay Var'Taka in the Drowned City."] = "在沉沒之城殺死瓦爾塔卡。",
  ["Slay Witch Doctor Zum'rah and bring Zum'rah's Head to Archmage Lan'dalock in Dalaran."] = "殺死巫醫祖穆拉恩，將祖穆拉恩的頭顱帶去給達拉然的大法師朗達拉克。",
  ["Slay Witch Doctor Zum'rah and bring Zum'rah's Head to Mazu'kon in Mulgore."] = "殺死巫醫祖穆拉恩，將祖穆拉恩的頭顱帶去給莫高雷的瑪庫可。",
  ["Slay the Mana Elemental in the City of Dalaran for High Sorcerer Andromath in Stormwind City."] = "為暴風城的高階巫師安多瑪斯殺死達拉然城中的法力元素。",
