  ["Spawns a common mining node over time and includes the Lodestone benefit."] = "會隨時間生成普通礦點，並包含磁石的效果。",
  ["Speak to Archmage Celindra in the City of Dalaran."] = "到達拉然城與大法師瑟琳卓交談。",
  ["Speak to Commander Ashlam Valorfist at Chillwind Camp."] = "與冰風崗的指揮官阿什拉姆·瓦羅菲斯特談一談。",
  ["Speak to Fahrad when you're ready to hear his plan."] = "準備好聽他的計畫時，和法拉德談談。",
  ["Speak to Mathrengyl Bearwalker at the Cenarion Enclave in Darnassus."] = "與達納蘇斯的塞納裏奧區的瑪斯雷·馭熊者談壹談。",
  ["Speak with Deathguard Baldren about the mysterious Earthen Ring travelers who recently passed through The Sepulcher."] = "和亡靈衛兵巴德瑞談談最近經過瑟伯切爾的神秘陶土議會旅人。",
  ["Speak with Katherine to learn more about Aeonas, and then find him in the Scarlet Monastery."] = "和凱薩琳談談，了解艾奧納斯的事，然後到血色修道院找到他。",
  ["Speak with Lumina Windsinger in the Sepulcher."] = "和瑟伯切爾的露蜜娜‧風詠談談。",
  ["Speak with Mayara Brightwing in the Burning Steppes."] = "與燃燒平原的瑪亞拉·布萊特文談一談。",
  ["Speak with Mordent Evenshade in Shen'dralas for information about the crystals you repaired."] = "和申德拉斯的摩丹特‧平影談談，打聽你修好的水晶的事。",
  ["Speak with Nathanos Blightcaller in the Eastern Plaguelands. He is said to have taken up residence at the Marris Stead. "] = "與東瘟疫之地的納薩諾斯·雕零者談一談。據說他居住在瑪瑞斯農場。",
  ["Speak with Ott and ask him to forge your blade."] = "和奧特談談，請他為你鍛造刀刃。",
  ["Speak with Sergeant Danneth at Nethergarde Keep."] = "和守望堡的丹尼斯中士談談。",
  ["Speak with Sergeant Ulka to learn more about the situation on Alcaz Isle."] = "和烏爾卡中士談談，了解奧卡茲島的情況。",
  ["Speak with Shoni must be done first."] = "必須先完成「沉默的舒尼」。",
  ["Speak with Trevan Rol in the Sepulcher and bring him the materials he requires."] = "和瑟伯切爾的崔凡‧羅爾談談，把他需要的材料帶給他。",
  ["Speak with the Fallen Hero of the Horde at the entrance to the Blasted Lands."] = "到詛咒之地的入口去，與部落英雄的靈魂談一談。",
