  ["Start:"] = "起點：",
  ["Starts at"] = "起始於",
  ["Starts empty: right-click the band to add elements (gold, bags, durability, experience, location, clock, FPS, new trainer spells, Library Books, hearthstone, class reagent, guild, friends, mail, Value spec, the tabs of the OneForAll window) or to pin it. Pinned it stays open; else it folds up to a small tab 3 seconds after the mouse left it and opens while the mouse is on it. Click an element to open what belongs to it."] = "一開始是空的：在資訊列上按右鍵新增項目（金錢、背包、耐久度、經驗值、位置、時鐘、FPS、訓練師新法術、圖書館書籍、爐石、職業材料、公會、好友、郵件、價值專精、OneForAll 視窗的分頁），或把它釘住。釘住就一直打開；沒釘住的話，滑鼠離開 3 秒後會收成一個小分頁，滑鼠移上去就打開。點一個項目會打開它對應的東西。",
  ["Starts from General Drakkisath's Command, dropped by Overlord Wyrmthalak."] = "從維姆薩拉克掉落的「達基薩斯將軍的命令」開始。",
  ["Starts from Lonebrow's Journal, a drop in Razorfen Kraul."] = "從亨里格的日記開始，在剃刀沼澤內掉落。",
  ["Starts from the Small Scroll that Charlga Razorflank drops."] = "從卡爾加·刺肋掉落的小卷軸開始。",
  ["Starts with the Dark Iron Map. Dark Iron Spies in Dun Morogh carry it."] = "從黑鐵地圖開始。丹莫洛的黑鐵間諜身上帶著它。",
  ["Status"] = "狀態",
  ["Status from observed turn-ins, your bags and the last scanned bank. Right-click a book for a manual note."] = "狀態來自觀察到的交付、你的背包和最後一次掃描的銀行。右鍵點擊書本可加上手動註記。",
  ["Stay open"] = "保持打開",
  ["Steal 6 Feed Satchels from the Alliance farm in Meadowsbrook then return to Krom'rosh."] = "從草原溪地的聯盟農場竊取6個餵食背袋，然後回去找克隆羅許。",
  ["Steps"] = "步驟",
