  ["Stormwind Mage Quarter"] = "暴風城法師區",
  ["Stormwind's prison under the Mage Quarter. The inmates have revolted and Bazil Thredd's Defias now hold the cell blocks."] = "暴風城法師區底下的監獄。囚犯發動暴動，現在巴基爾·斯瑞德的迪菲亞佔據了牢房區。",
  ["Stormwind, Ironforge, Darnassus, Orgrimmar, Thunder Bluff and Undercity. Buffs that ran out there are shown once you leave."] = "暴風城、鐵爐堡、達納蘇斯、奧格瑪、雷霆崖和幽暗城。在那裡消失的增益效果，等你離開後才會顯示。",
