  ["Strength buff for resting players; exclusive with Strength of Earth Totem."] = "給休息中玩家的力量增益；與大地之力圖騰不能同時存在。",
  ["Stretched Footpads"] = "撐大的薄靴",
  ["Striking Staff"] = "打擊法杖",
  ["Strongly Scented Hood"] = "氣味強烈的兜帽",
  ["Study"] = "研究",
  ["Suffused Bindings"] = "元素灌能束腕",
  ["Suggested"] = "建議",
  ["Suggested:"] = "建議：",
  ["Suggestions only"] = "僅供建議",
  ["Suggests the cheapest item in your bags (value x stack), destroys it and loots with one click. Quest items, library books, recipes, set pieces, profession tools and items without value are never suggested. Items better than grey need a second click. /ofa cheapest shows it any time."] = "建議你背包中最便宜的物品（價值 × 堆疊數），一鍵摧毀它並拾取。任務物品、圖書館書籍、配方、套裝部件、專業工具和沒有價值的物品永遠不會被建議。比灰色好的物品需要點第二次。隨時可用 /ofa cheapest 查看。",
  ["Sully McCleary"] = "蘇利‧麥拉利",
  ["Summon a Twilight's Thrall from a conduit within the Twilight Shroud and capture it with Amberhall's Soulstone."] = "在暮光之罩中從導引裝置召喚暮光奴隸，然後用安珀荷的靈魂石捕獲它。",
  ["Summoned"] = "召喚出現",
  ["Summoned at the pool with the Mallet of Zul'Farrak."] = "用祖爾法拉克之槌在水池召喚。",
  ["Summoned by warlocks with the Dreadsteed quest."] = "由進行恐懼戰馬任務的術士召喚。",
  ["Summoned in the Great Ossuary for the paladin and shaman class quests."] = "在大藏骨堂中召喚，用於聖騎士和薩滿的職業任務。",
  ["Summoned in the Rookery when an egg hatches."] = "在育龍場有蛋孵化時出現。",
  ["Summoned with a brazier from the Tier 0.5 set quests."] = "用 T0.5 套裝任務的火盆召喚。",
  ["Summoned with the Fathom Core (quest Amongst the Ruins). Optional, not on the usual route."] = "用深淵核心召喚（任務「廢墟之間」）。可選，不在一般路線上。",
  ["Summoned with the quest Urok Doomhowl."] = "用任務「烏洛克」召喚。",
  ["Superior Cook"] = "高級廚師",
  ["Superior Fisherman"] = "高級漁夫",
  ["Superior Herbalist"] = "高級草藥師",
  ["Supple Scorpid Shoulder"] = "柔韌蠍子護肩",
  ["Supported Families"] = "支援的類別",
  ["Supreme Smasher"] = "至尊碎擊錘",
  ["Swipe 3 nearby enemies, inflicting 4 damage."] = "攻擊附近的3個敵人，對它們造成4點傷害。",
  ["Swipe 3 nearby enemies, inflicting damage."] = "揮擊附近3名敵人，造成傷害。",
  ["Switch"] = "切換",
  ["Switch it off when the game's own ? already shows on the map."] = "遊戲自己的 ? 已經會出現在地圖上時就關掉。",
  ["Switch this character to it now? The interface reloads."] = "現在要把這個角色切換過去嗎？介面會重新載入。",
  ["Switch this character to the profile"] = "要把這個角色切換到設定檔",
  ["Switch to it in Settings > Profiles."] = "可在「設定 > 設定檔」切換到它。",
  ["Switches on everything marked \"Recommended\". Nothing else is switched off."] = "開啟所有標示「推薦」的項目。其他項目不會被關閉。",
  ["Sword of Dismemberment"] = "肢解巨劍",
  ["Sword of Mourning"] = "悲慟之劍",
  ["Sword: you must kill it for a quest. Bag: it drops a quest item. With the progress (3/10); nothing once that part is done. Uses the quest lines the game shows in the mob's tooltip. Not inside dungeons yet."] = "劍：任務需要擊殺它。袋子：它會掉落任務物品。附帶進度（3/10）；那部分完成後就不顯示。使用遊戲在怪物提示框中顯示的任務文字。目前還不支援地城內。",
  ["Swords"] = "劍",
  ["Swordsmith Mitts"] = "鑄劍師手套",
  ["Sylvestris Dusksong"] = "希爾薇絲翠斯·暮歌",
  ["Syndicate Documents"] = "辛迪加文件",
  ["Syndicate Sabotage"] = "辛迪加的破壞",
  ["TEST"] = "測試",
  ["Tab"] = "分頁",
  ["Tab selection reset to the defaults for this character."] = "這個角色的分頁選擇已重置為預設值。",
  ["Tabard"] = "外袍",
  ["Tailoring Trainer"] = "裁縫訓練師",
  ["Tainted Hyjal Stag"] = "汙染的海加爾雄鹿",
  ["Take a Bloodpetal to Gregan Brewspewer in Feralas."] = "把血瓣花交給菲拉斯的格雷甘·山酒。",
  ["Take the Titan Relic to the Elder Rise in Thunder Bluff and look for someone who can tell you more about it."] = "把泰坦聖物帶到雷霆崖的長者高地，找一位能告訴你更多相關資訊的人。",
  ["Take the tablet etchings to Master Gadrin in Sen'jin Village in Durotar."] = "前往杜洛塔，將石板拓印交給森金村的加德林大師。",
  ["Takes everything at once when the game auto loots."] = "遊戲自動拾取時一次拿走全部。",
  ["Taking damage has a 15% chance to grant Enraging Light for 10 sec, causing your melee attacks to deal 20 Holy damage. Deals 3 times as much damage to Undead. (Proc chance: 15%, 15s cooldown)"] = "受到傷害時有15%的機率獲得激怒之光，持續10秒，使你的近戰攻擊造成20點神聖傷害。對不死族造成3倍傷害。（觸發機率：15%，冷卻15秒）",
  ["Taking damage while at or below 20% health grants you a shield, absorbing 480 damage for 10 sec. This effect can only trigger once every 4 min. (4m cooldown)"] = "生命力在20%以下時受到傷害，會讓你獲得一個護盾，吸收480點傷害，持續10秒。這個效果每4分鐘只能觸發一次。（冷卻4分鐘）",
  ["Taking damage while at or below 25% health causes you to restore 100 health and mana over 5 sec. This effect can only trigger once every 5 min. (5m cooldown)"] = "生命力在25%以下時受到傷害，會在5秒內恢復100點生命力和法力。這個效果每5分鐘只能觸發一次。（冷卻5分鐘）",
  ["Tale of I'lalai in Zandali"] = "贊達拉語的伊拉萊故事",
  ["Talent"] = "天賦",
  ["Talent Trees"] = "天賦樹",
  ["Talent data unavailable"] = "天賦資料無法使用",
  ["Talent dump failed:"] = "天賦匯出失敗：",
  ["Talent planner unavailable:"] = "天賦規劃器無法使用：",
  ["Talent preview APIs are not available on this client."] = "這個用戶端沒有天賦預覽功能。",
  ["Talents"] = "天賦",
  ["Talismans of Merit"] = "功勳護符",
  ["Talk of the Town"] = "城裡的話題",
  ["Talk to Pusillin and chase the imp through Warpwood Quarter until he fights; he drops the Crescent Key."] = "和普希林說話，追著這隻小鬼穿過扭木廣場，直到牠開打；牠會掉落月牙鑰匙。",
  ["Talk to someone in Stormwind Intelligence about acquiring a remote detonator."] = "找暴風城情報局的人談談取得遙控引爆器的事。",
  ["Talon of Tor'Rel"] = "托瑞爾之爪",
  ["Target"] = "選為目標",
  ["Target of players"] = "玩家的目標",
  ["Target:"] = "目標：",
  ["Tattered Explorer's Cuffs"] = "破爛的探險者腕輪",
  ["Tattered Kirin Tor Cloak"] = "破爛的祈倫托披風",
  ["Taunt the target, increasing the likelihood the creature will focus attacks on your pet."] = "嘲諷目標，使該生物更可能集中攻擊你的寵物。",
  ["Teaches you"] = "教你學會",
  ["Teaches you how to craft"] = "教你如何製作",
  ["Tears at an enemy's legs for 12 damage over 9 sec and reduces movement speed by 50% for 9 sec."] = "撕裂敵人的腿，在9秒內造成12點傷害，並使其移動速度降低50%，持續9秒。",
  ["Tears at an enemy's legs for 21 damage over 9 sec and reduces movement speed by 50% for 9 sec."] = "撕裂敵人的腿，在9秒內造成21點傷害，並使其移動速度降低50%，持續9秒。",
  ["Tears at an enemy's legs for 27 damage over 9 sec and reduces movement speed by 50% for 9 sec."] = "撕裂敵人的腿，在9秒內造成27點傷害，並使其移動速度降低50%，持續9秒。",
  ["Tears at an enemy's legs for 45 damage over 9 sec and reduces movement speed by 50% for 9 sec."] = "撕裂敵人的腿，在9秒內造成45點傷害，並使其移動速度降低50%，持續9秒。",
  ["Tears at an enemy's legs for 60 damage over 9 sec and reduces movement speed by 50% for 9 sec."] = "撕裂敵人的腿，在9秒內造成60點傷害，並使其移動速度降低50%，持續9秒。",
  ["Tears at an enemy's legs for damage over 9 sec and reduces movement speed by 50% for 9 sec."] = "撕扯敵人的腿，在9秒內造成傷害，並使其移動速度降低50%，持續9秒。",
  ["Tell me about new versions"] = "有新版本時通知我",
  ["Temple of Atal'Hakkar"] = "阿塔哈卡神廟",
  ["Tendonscraper Dagger"] = "刮腱匕首",
  ["Territory"] = "地區",
  ["Territory:"] = "地區：",
  ["Terunne Bearshaper"] = "特倫恩·熊形",
  ["Test"] = "測試",
  ["Test roll window with"] = "測試擲骰視窗，使用",
  ["Texture"] = "材質",
  ["Thank players who buff you"] = "感謝幫你上增益的玩家",
  ["Thank you for using OneForAll! Everything can be changed later in OneForAll > Quality of Life."] = "感謝使用 OneForAll！之後都能在「OneForAll > 生活便利」中更改。",
  ["Thanks for buffs: no buffs seen yet."] = "感謝增益：還沒看到任何增益效果。",
  ["Thanks:"] = "感謝：",
  ["That is not a OneForAll profile text."] = "這不是 OneForAll 的設定檔文字。",
  ["The Abandoned"] = "被遺棄者",
  ["The Amulet of Union is put together from the Gem of the Fourth and Fifth Khan, which drop from Veng and Maraudos inside Maraudon."] = "聯合護符由第四可汗寶石和第五可汗寶石組合而成，分別由瑪拉頓內的溫格和瑪拉多斯掉落。",
  ["The Baron"] = "男爵",
  ["The Capital Gardens of Eldre'Thalas, where the last Highborne of the Shen'dralar feed on the demon Immol'thar. Prince Tortheldrin rules from the library."] = "埃德雷·薩拉斯的首都花園，最後的辛德拉上層精靈在這裡吸取惡魔伊莫塔爾的力量。托塞德林王子在圖書館中統治。",
  ["The Celebrian Rod drops from Noxxion and the Celebrian Diamond from Lord Vyletongue. Then speak with Celebras the Redeemed after defeating Celebras the Cursed."] = "塞雷布拉斯節杖由諾克賽恩掉落，塞雷布拉斯鑽石由維利塔恩掉落。打敗被詛咒的塞雷布拉斯後，再和贖罪的塞雷布拉斯談話。",
  ["The Crest has no fixed spot. Players found it in the tower tops, in rooms next to The Baron and near Bjork."] = "紋章沒有固定位置。玩家曾在塔頂、男爵旁邊的房間和比約克附近找到它。",
  ["The Crusade's library and archive. Several quests ask you to bring back books kept here."] = "十字軍的圖書館和檔案室。有好幾個任務要你帶回放在這裡的書。",
  ["The Cult of the Damned's school of necromancy in the crypts beneath Caer Darrow. Darkmaster Gandling teaches the dark arts. Needs the Skeleton Key."] = "詛咒教派位於凱爾達隆地下墓穴的死靈學校。黑暗院長加丁在此傳授黑暗法術。需要骷髏鑰匙。",
  ["The Dark Crystal"] = "黑暗水晶",
  ["The Dark Iron capital deep inside Blackrock Mountain. Emperor Dagran Thaurissan rules from the Imperial Seat, with Princess Moira Bronzebeard at his side."] = "黑石山深處的黑鐵矮人首都。達格蘭·索瑞森大帝在帝王寶座上統治，茉艾拉·銅鬚公主在他身旁。",
  ["The Default profile cannot be deleted."] = "預設設定檔無法刪除。",
  ["The Default profile cannot be renamed."] = "預設設定檔無法重新命名。",
  ["The Defias prisoners in the Stockade drop the Red Wool Bandanas."] = "監獄裡的迪菲亞囚犯會掉落紅色毛料頭巾。",
  ["The Desert Rose"] = "沙漠玫瑰",
  ["The Dragon's Journal"] = "巨龍的日誌",
  ["The Elite of the Elite"] = "精英中的精英",
  ["The Essence of Eranikus drops from the Shade of Eranikus."] = "伊蘭尼庫斯精華由伊蘭尼庫斯的陰影掉落。",
  ["The Fifth Khan, a spirit in the orange wing. Part of The Pariah's Instructions."] = "第五可汗，橘色區域的一個靈魂。屬於「賤民的指引」。",
  ["The Fourth Khan, a spirit in the purple wing. Part of The Pariah's Instructions."] = "第四可汗，紫色區域的一個靈魂。屬於「賤民的指引」。",
  ["The Goddess Provides"] = "女神的恩賜",
  ["The Great Cat Spirit"] = "巨豹之靈",
  ["The Great Tree Provides"] = "巨樹的恩賜",
  ["The Great Windborne Cat Spirit"] = "偉大的風裔獵豹之靈",
  ["The Head of Balnazzar drops from Balnazzar behind the main gate."] = "巴納札爾的頭顱由正門後的巴納札爾掉落。",
  ["The Heart of the Void"] = "虛空之心",
  ["The High Chieftain"] = "最高酋長",
  ["The Honor of the Kor'kron"] = "柯爾克隆的榮耀",
  ["The Lost Runner"] = "失蹤的信使",
  ["The Mad King"] = "瘋狂的國王",
  ["The Man in the Iron Chains"] = "被鐵鍊束縛的男人",
  ["The Only Good Brinescale..."] = "唯一的好鹹鱗……",
  ["The Oracle Tree"] = "神諭之樹",
  ["The Orphan"] = "孤兒",
  ["The Questioner"] = "審問者",
  ["The Reliquary of Tyr"] = "提爾的聖匣",
  ["The Return of the King?"] = "王者歸來？",
  ["The Scarlet Crusade's training grounds and armory, where Herod, the Scarlet Champion, drills his recruits. The door needs the Scarlet Key from the Library."] = "血色十字軍的訓練場和軍械庫，血色勇士赫洛德在這裡操練新兵。門需要圖書館拿到的血色十字軍鑰匙。",
  ["The Search button of a recipe in Professions > All recipes asks the other OneForAll users who know it (blue marker); only a few of them answer, so it stays fast with many players. When off, you are not asked and do not search either. Guild members are always shared. Moved here from Settings in 6.1.0."] = "在「專業技能 > 所有配方」中，配方的「搜尋」按鈕會詢問會這個配方的其他 OneForAll 使用者（藍色標記）；只有少數人會回應，所以玩家很多時也能保持順暢。關閉時別人不會問你，你也不會去搜尋。公會成員一律會分享。6.1.0 起從「設定」移到這裡。",
  ["The Secret Prison"] = "秘密監獄",
  ["The Shattered Necklace drops from the Shadowforge and Stonevault dwarves in and around Uldaman."] = "破碎的項鏈由奧達曼內外的暗爐矮人和石窟矮人掉落。",
  ["The Sisterhood of Elune"] = "伊露恩姐妹會",
  ["The Talisman of Kazdor"] = "卡茲多咒符",
  ["The Tempest's Weapons"] = "風暴之武器",
  ["The Twin Bears"] = "雙子熊神",
  ["The Unadorned Seal of Ascension and the three gemstones drop in Lower Blackrock Spire; the forged seal opens Upper Blackrock Spire."] = "未鑲飾的晉升印章和三顆寶石在下層黑石塔掉落；鍛造好的印章可打開上層黑石塔。",
  ["The Wild King"] = "荒野之王",
  ["The auction house materials for the selected recipes (as many crafts as in their fields), as the shopping list \"OneForAll Profit\"."] = "選取配方要用的拍賣場材料（次數照各自那一格寫的），做成購物清單「OneForAll Profit」。",
  ["The bags full helper may suggest this item again."] = "「背包已滿小幫手」之後可能會再建議這個物品。",
  ["The bar opens from a bigger OneForAll button that you can drag anywhere (it is not tied to the minimap). Right-click that button to open OneForAll. Switching this off puts all buttons back on the minimap. Not together with \"Hide the OneForAll button\"."] = "按鈕列從一個較大的 OneForAll 按鈕展開，這個按鈕可以拖到任何地方（不會綁在小地圖上）。右鍵點擊這個按鈕可打開 OneForAll。關閉這個功能會把所有按鈕放回小地圖。不能和「隱藏 OneForAll 按鈕」同時使用：按鈕列需要它的按鈕。",
  ["The beta server does not send the details of this item yet."] = "測試伺服器目前還不會傳送這個物品的詳細資料。",
  ["The book count for the third tier is not confirmed yet. Rewards may change. Ctrl-click an item to try it on."] = "第三階要幾本書還沒確認，獎勵可能會變。按住 Ctrl 點物品可以試穿。",
  ["The book count for the third tier is not confirmed yet. WoW Forever is still in beta, so rewards may change. Ctrl-click an item to try it on."] = "第三階的書本數量尚未確認。魔獸世界：永恆仍在測試階段，獎勵可能會變。Ctrl-點擊物品可試穿。",
  ["The build does not fit the current talent trees (made for another game version?)."] = "這個配點不符合目前的天賦樹（為其他遊戲版本做的？）。",
  ["The build has an unknown format."] = "配點格式不明。",
  ["The build has more than 51 points."] = "這個配點超過 51 點。",
  ["The build skips required points or talents (made for another game version?)."] = "這個配點跳過了必要的點數或天賦（為其他遊戲版本做的？）。",
  ["The cards glow so you notice them."] = "卡片會發光讓你注意到。",
  ["The chat windows and the chat box."] = "聊天視窗和聊天輸入框。",
  ["The cheapest way from your skill to a target for every crafting profession: auction house prices from Auctionator, vendor prices and trainer fees, and what you already own counts as free."] = "每種製作專業從你的技能練到目標的最便宜路線：拍賣場價格來自 Auctionator，加上商人價格和訓練費用，你已經有的算免費。",
  ["The color of the OneForAll minimap button."] = "OneForAll 小地圖按鈕的顏色。",
  ["The colour of the bar's background; the gold line stays."] = "資訊列背景的顏色；金色那條線會留著。",
  ["The current profile as text to copy."] = "把目前的設定檔轉成文字以便複製。",
  ["The dungeon quest on this page"] = "本頁的地城任務",
  ["The fallen city of Stratholme. The Scarlet Crusade holds the bastion behind the main gate, Baron Rivendare and the Scourge rule the ziggurats behind the service gate."] = "淪陷的斯坦索姆城。血色十字軍佔據正門後的堡壘，瑞文戴爾男爵和天譴軍團統治側門後的通靈塔。",
  ["The fallen human capital above the Undercity. Scourge remnants roam the streets and a necromancer is gathering strength in the ruins."] = "幽暗城上方淪陷的人類首都。天譴殘黨在街道上遊蕩，一名死靈法師正在廢墟中積蓄力量。",
  ["The filter button is next to the Wishlist tab."] = "篩選按鈕在「願望清單」分頁旁邊。",
  ["The flight map opens at once at a flight master, and the flight map tooltip shows the flight time."] = "在飛行管理員處會立刻打開飛行地圖，飛行地圖的提示框會顯示飛行時間。",
  ["The follow-up with the same name (Ambassador Malcin) belongs to Razorfen Downs."] = "同名的後續任務（大使瑪爾辛）屬於剃刀高地。",
  ["The former gnome capital, flooded with radiation and taken over by troggs and the traitor Mekgineer Thermaplugg."] = "昔日的地精首都，如今充滿輻射，被穴居人和叛徒麥克尼爾·瑟瑪普拉格佔據。",
  ["The game did not let this character reach the other OneForAll users (low level?). Try again later."] = "遊戲不讓這個角色連到其他 OneForAll 使用者（等級太低？）。請稍後再試。",
  ["The game keeps the old OneForAll channels (it blocks them, /leave does nothing). They are harmless - OneForAll does not use them any more."] = "遊戲會留著舊的 OneForAll 頻道（遊戲擋住了，/leave 沒用）。它們沒有害處——OneForAll 已經不用了。",
  ["The game refuses the channel for this character right now (low level?)."] = "遊戲目前拒絕這個角色使用該頻道（等級太低？）。",
  ["The game's health bar texture is dark; with this the class colors use a plain bright bar."] = "遊戲的生命條材質偏暗；開啟後職業顏色會使用單純的明亮計量條。",
  ["The game's loot glow. Changes graphics settings; after switching it off, restart the game."] = "遊戲的戰利品發光效果。會改變顯示設定；關閉後請重新啟動遊戲。",
  ["The game's loot glow. Changes only this one game setting - your outline settings stay as they are. After switching it off, restart the game."] = "遊戲的戰利品發光效果。只改這一個遊戲設定——你的輪廓設定不變。關掉之後要重新啟動遊戲。",
  ["The game's own Auto Loot setting."] = "遊戲本身的自動拾取設定。",
  ["The game's own setting."] = "遊戲本身的設定。",
  ["The green arrow stays for upgrades in the best armor type of your class. Upgrades in a lighter type get a yellow arrow: warriors and paladins wear plate from level 40 (mail before), hunters and shamans mail from 40 (leather before), rogues and druids leather. Cloaks, jewelry, shields and weapons are not affected. Needs \"Gear Value\"."] = "你職業最適合的護甲類型的升級維持綠色箭頭。較輕護甲類型的升級會是黃色箭頭：戰士和聖騎士 40 級起穿鎧甲（之前是鎖甲），獵人和薩滿 40 級起穿鎖甲（之前是皮甲），盜賊和德魯伊穿皮甲。披風、飾品類、盾牌和武器不受影響。需要開啟「裝備價值」。",
  ["The heart of the Scarlet Monastery. Scarlet Commander Mograine and High Inquisitor Whitemane lead the Crusade from the cathedral. The door needs the Scarlet Key from the Library."] = "血色修道院的核心。血色十字軍指揮官莫格萊尼和大檢察官懷特邁恩在大教堂中領導十字軍。門需要圖書館拿到的血色十字軍鑰匙。",
  ["The helper only suggests poor and common items."] = "小幫手只會建議粗糙和普通物品。",
  ["The herb or ore vein near you sparkles."] = "你附近的草藥或礦脈會閃光。",
  ["The idol is carried by the strongest priest in the city."] = "神像在城裡最強的祭司身上。",
  ["The important class quests (abilities, pets, class items): what you have done and where the next quest starts."] = "重要的職業任務（技能、寵物、職業物品）：你已完成哪些，以及下一個任務從哪裡開始。",
  ["The important quests of this class"] = "這個職業的重要任務",
  ["The interface reloads."] = "介面會重新載入。",
  ["The lair of the black dragon Onyxia, deep in the Wyrmbog of Dustwallow Marsh. A raid for 40 players, opening on 9 December 2026. You need the Drakefire Amulet to enter (see Attunement). The loot list holds the drops known so far; the full table follows once the raid is open."] = "黑龍奧妮克希亞的巢穴，位於塵泥沼澤的巨龍沼澤深處。40 人團隊副本，2026 年 12 月 9 日開放。需要龍火護符才能進入（見「進入資格」）。戰利品清單是目前已知的掉落；副本開放後會補上完整掉落表。",
  ["The language changes after a reload of the interface."] = "重新載入介面後才會換語言。",
  ["The language of OneForAll's texts. Names of items, spells and zones come from your game client."] = "OneForAll 文字的語言。物品、法術和地區的名稱來自你的遊戲用戶端。",
  ["The last profession window showed another player's recipes (a link or guild member) - not stored."] = "上一次的專業技能視窗顯示的是其他玩家的配方（連結或公會成員）——未儲存。",
  ["The lower halls of Blackrock Spire, held by the Blackrock orcs, Firebrand Legion and Smolderthorn trolls. Overlord Wyrmthalak commands them."] = "黑石塔的下層大廳，由黑石獸人、火印軍團和焦棘食人妖佔據。由維姆薩拉克指揮。",
  ["The map X marks the cave entrance. Inside, near the Wailing Caverns portal: 52.8, 54.7 on the cave map."] = "地圖上的 X 標示洞穴入口。進去後在哀嚎洞穴傳送門附近：洞穴地圖上的 52.8, 54.7。",
  ["The map button outlines the area where the mob or herb spawns."] = "地圖按鈕會框出怪物或草藥出現的範圍。",
  ["The monastery cemetery, where the Scarlet Crusade buries its fallen - and where the dead do not stay quiet."] = "修道院的墓地，血色十字軍在這裡埋葬陣亡者——而死者在這裡並不安息。",
  ["The plan keeps its recipes so the amounts do not jump. Click to work it out again with the current prices and what you have."] = "計畫會保留它的配方，數量才不會跳來跳去。點擊會照現在的價格和你有的東西重新算一次。",
  ["The power source is the Shattered Necklace Power Source from Archaedas."] = "能量源是阿札達斯掉落的破碎的項鏈能量源。",
  ["The preview loadout was rejected."] = "預覽的天賦配置被拒絕了。",
  ["The quest icons also when you zoom out of a zone."] = "縮小到區域以外時也顯示任務圖示。",
  ["The quest text mentions Kin'weelay, the troll scholar at Grom'gol Base Camp."] = "任務文字提到格羅姆高營地的食人妖學者肯維雷。",
  ["The quilboar's thorny burial grounds, now in the hands of the Scourge. Amnennar the Coldbringer leads the Death's Head from the depths."] = "野豬人布滿荊棘的墓地，如今落入天譴軍團手中。寒冰之王亞門納爾從深處率領亡首教派。",
  ["The radius of your totems that affect friendly targets is increased to 30 yd."] = "你的圖騰影響友方目標的有效範圍增加至30碼。",
  ["The round border and the compass are hidden; minimap buttons of other addons follow the square edge. Does nothing with ElvUI or when another addon already makes the minimap square."] = "圓形外框和指北針會隱藏；其他插件的小地圖按鈕會沿著方形邊緣排列。使用 ElvUI 或已有其他插件把小地圖改成方形時，這個選項沒有作用。",
  ["The ruby, sapphire and topaz are in chests across Uldaman; one of them is in Ironaya's chamber."] = "紅寶石、藍寶石和黃寶石放在奧達曼各處的箱子裡；其中一個在艾隆納亞的房間。",
  ["The sacred caverns of the centaur and the resting place of Zaetar. His corrupted daughter, Princess Theradras, waits at the bottom of the Earth Song Falls."] = "半人馬的聖地洞穴，也是札爾塔的安息之所。他被腐化的女兒瑟萊德絲公主在大地之歌瀑布底部等著。",
  ["The same font size for every chat window."] = "每個聊天視窗使用相同字型大小。",
  ["The same quests as the quest icons on the world map: for your level, side, race and class, pre-quests done. Off while Questie is loaded (it shows its own)."] = "跟世界地圖上任務圖示同一批任務：符合你的等級、陣營、種族和職業、前置任務已完成的。有載入 Questie 時會關掉（它會顯示自己的）。",
  ["The server does not send the details of this item yet."] = "伺服器還沒送出這個物品的詳細資料。",
  ["The server says this book quest is completed, but this addon did not see the turn-in. Use /ofa debug for IDs."] = "伺服器說這本書的任務已經完成，但這個插件沒看到交付。用 /ofa debug 看 ID。",
  ["The spies near Ironband's Compound carry the map"] = "鐵環營地附近的間諜身上帶著地圖",
  ["The stat weights of this spec are used for the upgrades here, in tooltips, bags and loot rolls. \"Active spec\" follows your talents. \"Edit custom weights...\" sets your own weights."] = "這個專精的屬性權重會用在這裡的升級、提示框、背包和戰利品擲骰。「目前專精」會跟著你的天賦。「編輯自訂權重……」可設定你自己的權重。",
  ["The sun-baked capital of the Sandfury trolls in northern Tanaris. Chief Ukorz Sandscalp rules from the city, and Gahz'rilla sleeps in its sacred pool."] = "塔納利斯北部被烈日曬烤的沙怒食人妖首都。烏克茲·沙頂從城中統治，加茲瑞拉沉睡在神聖水池中。",
  ["The sunken temple of the Atal'ai trolls, who try to summon their god Hakkar. The green dragonflight guards the lower halls against them."] = "阿塔萊食人妖的沉沒神廟，他們想召喚他們的神祇哈卡。綠龍軍團在下層大廳阻擋他們。",
  ["The talents shown here as a short text to copy and share. Import reads it again."] = "這裡顯示的天賦轉成一段短文字，方便複製和分享。「匯入」可再讀回來。",
  ["The test roll window could not be opened."] = "無法打開測試擲骰視窗。",
  ["The time also shows in the tooltip of the destinations on the flight map. OneForAll measures your flights; routes you never flew are estimated (\"about\")."] = "時間也會顯示在飛行地圖上目的地的提示框中。OneForAll 會記錄你的飛行；從沒飛過的路線是估計值（「約」）。",
  ["The time bar under it is as wide as the icon. Several icons sit next to each other."] = "下方的時間條和圖示一樣寬。多個圖示會並排。",
  ["The tooltip names the other zone; a click shows it on the map. Places from the addon Carbonite (GPL)."] = "提示框會顯示另一個區域的名稱；點擊會在地圖上顯示它。地點來自插件 Carbonite（GPL）。",
  ["The upgrade arrows and percentages now use stat weights based on SimGear Forever by Frostmil, with our own changes for leveling: Intellect and Spirit for casters and healers, Stamina, mana and health per 5 sec."] = "升級箭頭和百分比現在用以 Frostmil 的 SimGear Forever 為基礎的屬性權重，再加上我們為練等做的調整：法系和治療用智力和精神，還有耐力、每5秒法力和生命力。",
  ["The upper spire of the Black Dragonflight. Warchief Rend Blackhand rides from the Hordemar City arena, and General Drakkisath guards the way to Blackwing Lair. Needs the Seal of Ascension. In Forever a 10-player dungeon."] = "黑龍軍團盤踞的上層黑石塔。大酋長雷德·黑手從部落城競技場出擊，達基薩斯將軍守著通往黑翼之巢的路。需要晉升印章。在永恆中是 10 人地城。",
  ["The wishlist is in Armory > Gear Planner."] = "願望清單在「軍械庫 > 裝備規劃器」裡。",
  ["The wolf howls, increasing the melee attack power of all party members within 15 yards.  Lasts 1 min."] = "狼發出嚎叫，使15碼內所有隊伍成員的近戰攻擊強度提高。持續1分鐘。",
  ["The wolf howls, increasing the melee attack power of all party or raid members within 15 yards by 13.  Lasts 1 min."] = "狼發出嚎叫，使15碼內所有隊伍或團隊成員的近戰攻擊強度提高13點。持續1分鐘。",
  ["The wolf howls, increasing the melee attack power of all party or raid members within 15 yards by 31 to 38.  Lasts 1 min."] = "狼發出嚎叫，使15碼內所有隊伍或團隊成員的近戰攻擊強度提高31到38點。持續1分鐘。",
  ["The wolf howls, increasing the melee attack power of all party or raid members within 15 yards by 68.  Lasts 1 min."] = "狼發出嚎叫，使15碼內所有隊伍或團隊成員的近戰攻擊強度提高68點。持續1分鐘。",
  ["The wolf howls, increasing the melee attack power of all party or raid members within 15 yards by 84.  Lasts 1 min."] = "狼發出嚎叫，使15碼內所有隊伍或團隊成員的近戰攻擊強度提高84點。持續1分鐘。",
  ["The wolf howls, increasing the melee attack power of all party or raid members within 15 yards.  Lasts 1 min."] = "狼發出嚎叫，提高15碼內所有隊伍或團隊成員的近戰攻擊強度。持續1分鐘。",
  ["The word players whisper you to get an invite."] = "玩家密語你這個字就會收到邀請。",
  ["The world map cannot be switched by the addon during combat."] = "戰鬥中插件無法切換世界地圖。",
  ["The world map could not be opened."] = "無法打開世界地圖。",
  ["The world map normally hides the areas you have not visited. With this the whole zone map is shown. The slider sets how visible the unexplored parts are (0 % hidden, 100 % fully shown)."] = "世界地圖通常會隱藏你沒去過的地方。開啟後會顯示整張區域地圖。滑桿可設定未探索部分的清楚程度（0% 隱藏，100% 完全顯示）。",
  ["The zone's level range at the top right of the world map and when you hover a zone."] = "在世界地圖右上角和滑鼠移到區域時，顯示該區域的等級範圍。",
  ["Theka's Last Breath"] = "塞卡的最後一口氣",
  ["Theramore Defender's Gauntlets"] = "塞拉摩防衛者護手",
  ["There the tooltip stays at its usual place."] = "在那裡提示框維持原本的位置。",
  ["Thermaplugg's Engineering Notes"] = "瑟瑪普拉格的工程筆記",
  ["These action buttons use a lower rank than you know."] = "這些快捷列按鈕用的等級比你已學會的低。",
  ["Thicker Than Water"] = "血濃於水",
  ["Thicket Lurker"] = "灌木潛伏者",
  ["Thicket Matriarch"] = "灌木女族長",
  ["This Land Was Their Land"] = "這片土地曾屬於他們",
  ["This boss has no boss-specific loot - it only drops random world items (the same as in Classic)."] = "這個首領沒有專屬戰利品——只會掉落隨機的世界物品（和經典版一樣）。",
  ["This can be changed after combat."] = "這可以在戰鬥結束後更改。",
  ["This character and all others using it go back to Default. The interface reloads."] = "這個角色和其他所有使用它的角色都會回到預設值。介面會重新載入。",
  ["This character uses"] = "這個角色使用",
  ["This character's list. Sell junk sells these items too."] = "這個角色的清單。「出售垃圾」也會賣掉這些物品。",
  ["This client has no loot roll window to test."] = "這個用戶端沒有可以測試的戰利品擲骰視窗。",
  ["This client's quest log cannot be read."] = "無法讀取這個用戶端的任務日誌。",
  ["This entrance position has not been verified in game yet."] = "這個入口位置還沒在遊戲中確認過。",
  ["This loot is worth less than anything in your bags."] = "這個戰利品比你背包裡任何東西都不值錢。",
  ["This option changes soft-targeting, read hint text!"] = "這個選項會改變軟目標設定，請閱讀提示文字！",
  ["This quest is not in your quest log."] = "這個任務不在你的任務日誌裡。",
  ["This session"] = "這次登入",
  ["This set exists in the game files, but its source (raid, battleground ranks, event, ...) is not part of WoW Forever yet."] = "遊戲檔案裡有這個套裝，但它的來源（團隊副本、戰場軍銜、活動……）目前還不在魔獸世界：永恆中。",
  ["Thom Filch"] = "湯姆·費爾奇",
  ["Thorn Protecting Girdle"] = "荊棘護衛腰帶",
  ["Thornplated Cord"] = "棘鎧之索",
  ["Threat from Below"] = "來自地底的威脅",
  ["Thunderhoof"] = "雷蹄",
  ["Tidebound Dagger"] = "潮縛匕首",
  ["Tidemistress Ca'zass"] = "潮汐女士卡札斯",
  ["Tidesoaked Leggings"] = "潮浸護腿",
  ["Tidesong Wand"] = "潮歌魔杖",
  ["Tier"] = "套裝等級",
  ["Time-Forgotten Bindings"] = "遺忘時光束腕",
  ["Time-Lost Battalion"] = "時佚營隊",
  ["Timed event: reach the Baron before Ysida dies."] = "限時事件：在伊思達死去之前趕到男爵那裡。",
  ["Titanosaur"] = "泰坦巨龍",
  ["Titanosaur Scale Pendant"] = "泰坦龍鱗墜飾",
  ["To"] = "前往",
  ["To Darnassus"] = "前往達納蘇斯",
  ["To Thunder Bluff"] = "前往雷霆崖",
  ["To buy"] = "要買的",
  ["To get"] = "還要取得",
  ["Toofbreaker"] = "圖夫碎牙者",
  ["Tooltip at the mouse"] = "提示框跟著滑鼠",
  ["Tooltip data"] = "提示框資料",
  ["Tooltip position"] = "提示框位置",
  ["Tooltips"] = "提示框",
  ["Tooltips that normally appear at the bottom right show at your mouse."] = "原本出現在右下角的提示框，改在滑鼠旁邊顯示。",
  ["Tooth of the Matriarch"] = "族母之牙",
  ["Top"] = "上",
  ["Top center"] = "中上",
  ["Top left"] = "左上",
  ["Top right"] = "右上",
  ["Tor'Rel"] = "托瑞爾",
  ["Tormented Cuffs"] = "痛苦腕輪",
  ["Torn Cultist Cloak"] = "破裂教徒披風",
  ["Toron Rockhoof"] = "托隆·石蹄",
  ["Total"] = "總計",
  ["Totemic"] = "圖騰",
  ["Touch of the Depths"] = "深淵染指",
  ["Town Clerk's Mittens"] = "鎮書記的連指手套",
  ["Tracker Stillwind"] = "追蹤者靜風",
  ["Trade Goods"] = "商品",
  ["Trade hub"] = "貿易中心",
  ["Trade supplies vendors sell these (in every big city):"] = "商業用品商人有賣這些（每個大城都有）：",
  ["Trainer"] = "訓練師",
  ["Trainer button in the spellbook"] = "法術書中的訓練師按鈕",
  ["Training"] = "訓練",
  ["Training costs are not part of the game data. They are filled in when you open your class trainer."] = "訓練費用不在遊戲資料中。打開你的職業訓練師時會自動填入。",
  ["Translated Tale of I'lalai"] = "翻譯過的伊拉萊故事",
  ["Translucent ghostly cat summoned from cat figurines at Ruins of Mathystra; keeps its look after taming; teaches Claw 3."] = "在瑪塞斯特拉廢墟用貓雕像召喚出來的半透明幽靈豹；馴服後保持外觀；會教爪擊 3。",
  ["Transmut"] = "轉化",
  ["Trapper's"] = "設陷者",
  ["Trash"] = "小怪",
  ["Trauma Surgeon"] = "創傷外科醫生",
  ["Travel to Blackmaw Hold in Kalimdor, and recover the Reliquary of Tyr."] = "前往卡林多的黑喉要塞，取回提爾的聖匣。",
  ["Travel to Blackrock Spire and destroy War Master Voone, Highlord Omokk, and Overlord Wyrmthalak. Return to Marshal Maxwell when the job is done."] = "到黑石塔去消滅指揮官沃恩、歐莫克大王和維姆薩拉克。完成任務之後回到麥克斯韋爾元帥處復命。",
  ["Travel to Blackrock Spire and slay Shadow Hunter Vosh'gajin. Recover Vosh'gajin's Snakestone and return to Kilram."] = "到黑石塔去殺死暗影獵手沃什加斯，將沃什加斯的菊石交給基爾拉姆。",
  ["Travel to Dire Maul in Feralas and recover 15 Satyr Blood from the Wildspawn Satyr that inhabit the Warpwood Quarter. Return to Daio in the Tainted Scar when this is done. "] = "到菲拉斯的厄運之槌去，從扭木廣場的荒野薩特身上找到15份薩特之血，然後把它們交給腐爛之痕的戴奧。",
  ["Travel to Dire Maul to acquire a Felvine Seed from Alzzin the Wildshaper, an Ancient Memento from Prince Tortheldrin, and an Earthstone Diamond Pinky Ring from King Gordok, and bring them to Pix Xizzix in Booty Bay."] = "前往厄運之槌，從奧茲恩身上取得魔藤種子、從托塞德林王子身上取得上古紀念物、從戈多克大王身上取得地石鑽石尾戒，然後把它們交給藏寶海灣的皮克斯‧希吉克斯。",
  ["Travel to Krol'dok Stronghold and slay Zalfan Moonshadow."] = "前往克羅多克要塞，並殺死薩爾凡‧月影。",
  ["Travel to Marvon Rivetseeker's workshop in Ratchet."] = "到棘齒城去，在瑪爾馮·瑞文斯克的車間裡找到他。",
  ["Travel to Nethergarde Keep in the Blasted Lands and locate Sergeant Danneth."] = "前往詛咒之地的守望堡，找到丹尼斯中士。",
  ["Travel to The Sepulcher in Silverpine Forest and speak with Trevan Rol about the missing Earthen Ring travelers."] = "前往銀松森林的瑟伯切爾，和崔凡‧羅爾談談失蹤的陶土議會旅人。",
  ["Travel to the Burning Steppes and give Bijou's Information to Marshal Maxwell."] = "到燃燒平原去，把比修的情報交給麥克斯韋爾元帥。",
  ["Travel to the Dwarven District in Stormwind and find an engineer who can help."] = "前往暴風城的矮人區，找一位能幫忙的工程師。",
  ["Treacherous Cold"] = "險惡的嚴寒",
  ["Tree"] = "天賦樹",
