  ["Untick to never get a popup for beasts teaching this ability."] = "取消勾選後，會教這個技能的野獸就不會再跳出提醒。",
  ["Unverified: the server reports this quest completed, but this addon did not observe the turn-in."] = "未確認：伺服器回報這個任務已完成，但這個插件沒看到交付。",
