  ["Ursine Hammer"] = "熊之錘",
  ["Usable campsite anvil plus the Sharpening Wheel benefit."] = "可使用的營地鐵砧，加上砂輪的效果。",
  ["Use"] = "使用",
  ["Use Jaron's Pick to find the four Highborne Relic Fragments. Bring them to Aurora Skycaller in Eastern Plaguelands."] = "使用加隆的鎬來尋找四塊上層精靈遺物的碎片，把它們交給東瘟疫之地的奧蘿拉。",
  ["Use the Fathom Core from Amongst the Ruins to summon Baron Aquanis."] = "使用「廢墟之間」任務得到的深淵核心來召喚阿奎尼斯男爵。",
  ["Use the Moonsilver Blade to destroy Old Fire-Eye in Silverpine Forest."] = "用月銀刃在銀松森林消滅老火眼。",
  ["Use the Moonsilver Blade to destroy Old-Fire Eye in Silverpine Forest."] = "到銀松森林用月銀刃摧毀老火眼。",
  ["Use the SI:7 Disguise Kit to eavesdrop on Jaina and her inner circle at the Theramore Mage Tower."] = "使用軍情七處偽裝工具，在塞拉摩法師塔偷聽珍娜和她的親信。",
  ["Use the game's Edit Mode: Game Menu > Edit Mode, then drag the minimap."] = "用遊戲的編輯模式：遊戲選單 > 編輯模式，再拖曳小地圖。",
  ["Use the hide and charcoal to create a rubbing of the Third Troll Legend tablet."] = "使用獸皮和炭筆拓印食人妖傳說第三章的石板。",
  ["Use the hide and charcoal to create rubbings of the tablets found in the Drowned City."] = "用獸皮和木炭拓印沉沒之城中找到的石板。",
  ["Use: Breathe dragonfire in a narrow cone, dealing 450 Fire damage immediately and 125 every 2 sec for 8 sec. 2 min cooldown."] = "使用：朝狹窄錐形範圍噴吐龍火，立即造成450點火焰傷害，並在8秒內每2秒造成125點傷害。冷卻2分鐘。",
  ["Use: Gain 10 charges of Venomous Blood for 20 sec. When you take bleed damage, a charge jumps to an enemy within 8 yd and deals 325 Nature damage when it expires. 2 min cooldown."] = "使用：獲得10層毒血，持續20秒。你受到流血傷害時，會有一層跳到8碼內的一名敵人身上，消失時造成325點自然傷害。冷卻2分鐘。",
  ["Use: Increases healing by 28 for 30 sec. Shares the potion cooldown."] = "使用：治療量提高28點，持續30秒。與藥水共用冷卻時間。",
  ["Use: Increases spell damage by 265 against elementals for 2 min. 2 min cooldown."] = "使用：對元素生物的法術傷害提高265點，持續2分鐘。冷卻2分鐘。",
  ["Use: Throw a caustic cloud lasting 12 sec; enemies inside take 285-315 Nature damage each second. 2 min cooldown."] = "使用：擲出一團持續12秒的腐蝕雲霧；裡面的敵人每秒受到285～315點自然傷害。冷卻2分鐘。",
  ["Use: Throw a cloud that lasts 8 sec; enemies inside have 15% reduced chance to hit. 2 min cooldown."] = "使用：擲出一團持續8秒的雲霧；裡面的敵人命中率降低15%。冷卻2分鐘。",
  ["Valley of Spirits"] = "精神谷",
  ["Value per point of each stat for this character (hit, crit, dodge ... per 1 %). 0 or empty = the stat does not count. Used while \"Custom weights\" is picked."] = "這個角色每種屬性每一點的價值（命中、致命一擊、閃躲……以每 1 % 計）。0 或空白＝這項屬性不計入。選「自訂權重」時使用。",
