  ["Venture to Maraudon and recover a Vial of Earth Song Water and return it to Woodwyrd at the Forlorn Gardens in Desolace."] = "深入瑪拉頓，取回一瓶大地之歌泉水，交給淒涼之地遺忘花園的伍德維德。",
  ["Venture to Razorfen Downs and acquire Virulent Blood of Agamaggan, then return it to Kog'thug the Brave at Bristleback Retreat in the Desolace. Kog'thug felt it worth reminding that the Blood of Agamaggan inside Razorfen Kraul would not be sufficient."] = "前往剃刀高地取得劇毒的阿迦瑪甘之血，然後交給淒涼之地刺背居所的『勇者』柯薩。柯薩特別提醒：剃刀沼澤裡的阿迦瑪甘之血是不夠的。",
