  ["Warpwood Bracers"] = "曲木護腕",
  ["Warpwood Quarter of the ancient Highborne city of Eldre'Thalas, overgrown by corrupted ancients and satyrs. Alzzin the Wildshaper tends the Felvine."] = "上層精靈古城埃德雷·薩拉斯的扭木廣場，長滿了腐化的古樹和薩特。奧茲恩照料著魔藤。",
