  ["Waylaid Crates are world drops. Use a crate to reveal its shipment, provide one complete material bundle, then deliver the sealed crate to your faction's supply representative."] = "遭攔截的木箱是世界掉落物。使用木箱可以看到它的貨物內容，交出一整份完整的材料包，再把封好的木箱交給你陣營的補給代表。",
