  ["West of the Crossroads"] = "十字路口西邊",
  ["What an item is worth disenchanted, at auction house prices."] = "物品分解後值多少，照拍賣場價格算。",
  ["What can I do with the books?"] = "這些書能拿來做什麼？",
  ["What can I do?"] = "我能做什麼？",
  ["What is already in your bags is taken off."] = "背包裡已經有的會扣掉。",
  ["What the class trainer teaches."] = "職業訓練師教什麼。",
  ["What the pet trainers teach (Growl, Great Stamina, Natural Armor, resistances ...) and where the pet trainers of your faction are."] = "寵物訓練師教什麼（低吼、強效耐力、自然護甲、抗性……），以及你陣營的寵物訓練師在哪裡。",
  ["What the pet trainers teach, and where (your faction)"] = "寵物訓練師教什麼，以及在哪裡（你的陣營）",
  ["What this class can learn"] = "這個職業可以學什麼",
  ["What you already have (bags, bank) is taken off."] = "會扣掉你已經有的（背包、銀行）。",
  ["What you already have (bags, bank, other characters) is taken off."] = "會扣掉你已經有的（背包、銀行、其他角色）。",
  ["What you can still learn"] = "你還能學什麼",
  ["What you can still learn for your pet, and where"] = "你的寵物還能學什麼，以及在哪裡",
  ["What you share with your guild members who also use OneForAll."] = "你跟也用 OneForAll 的公會成員分享什麼。",
  ["What's the Big Idea?"] = "搞什麼名堂？",
  ["When a group member can still accept one of your dungeon quests."] = "有隊伍成員還能接你的地城任務時。",
  ["When loot does not fit, offers to destroy the cheapest item."] = "戰利品放不下時，提議摧毀最便宜的物品。",
  ["When struck by a harmful spell, has a 7% chance of Silencing the caster for 3 sec. Can only occur once every 60 sec. (Proc chance: 7%, 1m cooldown)"] = "受到有害法術攻擊時，有7%的機率使施法者沉默3秒。每60秒最多觸發一次。（觸發機率：7%，冷卻1分鐘）",
  ["When struck in combat has a 2% chance of causing the attacker to flee in terror for 2 sec. Can only occur once every 60 sec. (Proc chance: 2%, 1m cooldown)"] = "受到攻擊時，有2%的機率使攻擊者恐懼逃跑2秒。每60秒最多觸發一次。（觸發機率：2%，冷卻1分鐘）",
  ["When struck in combat has a 2% chance of freezing the attacker in place for 3 sec. Can only occur once every 60 sec. (Proc chance: 2%, 1m cooldown)"] = "受到攻擊時，有2%的機率將攻擊者凍結在原地3秒。每60秒最多觸發一次。（觸發機率：2%，冷卻1分鐘）",
  ["When struck in combat has a 2% chance of shielding the wearer in a protective shield which will absorb 488 damage. Can only occur once every 60 sec. (Proc chance: 2%, 1m cooldown)"] = "受到攻擊時，有2%的機率為穿戴者套上保護護盾，吸收488點傷害。每60秒最多觸發一次。（觸發機率：2%，冷卻1分鐘）",
  ["When struck in combat has a chance of returning 300 mana, 10 rage, or 40 energy to the wearer. (Proc chance: 2%)"] = "在戰鬥中受到攻擊時，有一定機率為穿戴者恢復300點法力、10點怒氣或40點能量。（觸發機率：2%）",
  ["When struck in combat, has a 10% chance to remove a Disarm effect from yourself. Can only occur once every 60 sec. (Proc chance: 10%, 1m cooldown)"] = "受到攻擊時，有10%的機率移除你身上的一個繳械效果。每60秒最多觸發一次。（觸發機率：10%，冷卻1分鐘）",
  ["When struck in combat, has a 5% chance to increase your movement speed by 10% for 8 sec. Can only occur once every 60 sec. (Proc chance: 5%, 1m cooldown)"] = "受到攻擊時，有5%的機率使你的移動速度提高10%，持續8秒。每60秒最多觸發一次。（觸發機率：5%，冷卻1分鐘）",
  ["When struck in combat, has a 5% chance to remove a Snare effect from yourself. Can only occur once every 60 sec. (Proc chance: 5%, 1m cooldown)"] = "受到攻擊時，有5%的機率移除你身上的一個緩速效果。每60秒最多觸發一次。（觸發機率：5%，冷卻1分鐘）",
  ["When struck in combat, has a 8% chance to remove a Root effect from yourself. Can only occur once every 60 sec. (Proc chance: 8%, 1m cooldown)"] = "受到攻擊時，有8%的機率移除你身上的一個定身效果。每60秒最多觸發一次。（觸發機率：8%，冷卻1分鐘）",
  ["When struck in melee combat, has a 5% chance of Disarming the attacker for 4 sec. Can only occur once every 60 sec. (Proc chance: 5%, 1m cooldown)"] = "受到近戰攻擊時，有5%的機率繳械攻擊者4秒。每60秒最多觸發一次。（觸發機率：5%，冷卻1分鐘）",
  ["When struck in melee there is a 50% chance you will Fade for 4 sec. (Proc chance: 50%, 5s cooldown)"] = "受到近戰攻擊時有50%的機率使你漸隱4秒。（觸發機率：50%，冷卻5秒）",
  ["When you cast a Healing Wave or Lesser Healing Wave, there is a 25% chance the target also receives a free Lightning Shield that causes 50 Nature damage to attacker on hit. (Proc chance: 25%)"] = "施放治療波或次級治療波時，有25%的機率讓目標同時獲得一個免費的閃電之盾，對攻擊者造成50點自然傷害。（觸發機率：25%）",
  ["When your Mana falls below 15%, restore 200 Mana over 10 sec. Restores twice as much Mana in Haunted and Wasteland areas. May only occur once every 5 min. (5m cooldown)"] = "當你的法力低於15%時，在10秒內恢復200點法力。在鬧鬼地區和荒地區域恢復的法力加倍。每5分鐘只能觸發一次。（冷卻5分鐘）",
  ["When your health drops below 20%, for the next 5 seconds healing spells cast on you help you to Cheat Death, increasing healing done by up to 160."] = "當你的生命力低於20%時啟動，在5秒內施放在你身上的治療法術能幫你啟動死亡謊言，提高被治療的效果最多160點。",
  ["Where the bar opens next to the OneForAll button."] = "按鈕列在 OneForAll 按鈕旁的展開位置。",
  ["Where the mark sits on the nameplate."] = "標記在名條上的位置。",
  ["Where this recipe comes from is not known yet."] = "還不知道這個配方從哪裡來。",
  ["Where to get it is not known."] = "不知道哪裡可以取得。",
  ["Where to report bugs and ideas (GitHub or CurseForge), with your last errors to copy."] = "回報錯誤和建議的地方（GitHub 或 CurseForge），附上你最近的錯誤方便複製。",
  ["Where to report bugs and ideas (our Discord), with your last errors to copy."] = "回報錯誤和點子的地方（我們的 Discord），附上你最近的錯誤可以複製。",
  ["Where to tame"] = "馴服地點",
  ["Whether you, an alt or a guild member knows a recipe."] = "你、你的分身或公會成員是否會某個配方。",
  ["Which recipes are worth crafting right now: material costs against the auction house price, with the investment and profit of your selection."] = "哪些配方現在值得做：材料成本對拍賣場價格，加上你選取的投入和利潤。",
  ["While flying a small window shows the time left; the times get more exact with every flight."] = "飛行時有小視窗顯示剩餘時間；每飛一次時間就會更準確。",
