  ["Yes"] = "是",
  ["You"] = "你",
  ["You are already at this skill. Set a higher target."] = "你已經是這個技能等級了。設一個更高的目標。",
  ["You are not in a group."] = "你不在隊伍中。",
  ["You can also skip this: everything can be changed later in OneForAll > Quality of Life."] = "你也可以跳過：之後都能在「OneForAll > 生活便利」中更改。",
  ["You can open this window with Alt + right-click on the minimap button."] = "在小地圖按鈕上按 Alt + 右鍵也能打開這個視窗。",
  ["You can start here in Auberdine; the lead-in from Argos Nightwhisper in Stormwind is not required."] = "你可以直接在奧伯丁開始；暴風城阿古斯·夜語的前導任務不是必要的。",
  ["You do not know this recipe yet."] = "你還不會這個配方。",
  ["You get:"] = "你會得到：",
  ["You have"] = "你有",
  ["You have a chance whenever you deal ranged damage to apply an Expose Weakness effect to the target. Expose Weakness increases the Ranged Attack Power of all attackers against that target by 450 for 7 sec."] = "在你對目標造成遠程攻擊傷害時，有一定機率使其獲得破甲虛弱效果。這個效果可以令所有遠程攻擊對該目標的攻擊強度提高450點，持續7秒。",
  ["You have everything"] = "你都有了",
  ["You have it"] = "你已擁有",
  ["You know every weapon skill of your class"] = "你已學會你職業所有的武器技能",
  ["You know this recipe"] = "你已學會這個配方",
  ["You need Gnogaine from Ozzie Togglevolt in Kharanos first. The collected fallout decays fast, so hurry back."] = "你要先從卡拉諾斯的奧齊·電環那裡拿到諾恩。收集到的放射性落塵衰減得很快，要盡快回去。",
  ["You still pick rewards yourself."] = "獎勵仍由你自己選。",
  ["You tear the note from the plank and read the scrawled writing."] = "你把紙條從木板上撕下來，讀著上面潦草的字跡。",
  ["You will also receive:"] = "你還可以得到：",
  ["Young Crocolisk"] = "幼鱷魚",
  ["Young Riptooth"] = "年輕的裂牙",
  ["Youngster's First Bow"] = "年輕人的第一把弓",
  ["Your Backstab, Sinister Strike, and Hemorrhage critical hits cause you to regain 5 energy. (500ms cooldown)"] = "你的背刺、邪惡攻擊和出血造成致命一擊時，恢復5點能量。（冷卻0.5秒）",
  ["Your Blizzard spell has a 30% chance to be uninterruptible."] = "你的暴風雪法術有30%的機率完全不被打斷。",
  ["Your Cleanse spell also heals the target for 200."] = "淨化法術同時治療目標200點生命。",
  ["Your Eviscerate has a chance per combo point to reveal a flaw in your opponent's armor, granting a 100% critical hit chance for your next Backstab, Sinister Strike, or Hemorrhage."] = "每一點剔骨點數將有機會識破敵人護甲的弱點並令下一個背刺、邪惡攻擊、或出血有100%的機率造成致命一擊。",
  ["Your Flash of Light and Holy Light spells have a chance to imbue your target with Holy Power. (Proc chance: 10%)"] = "你的聖光閃現和聖光術有一定機率使目標獲得神聖能量。（觸發機率：10%）",
  ["Your Frostfire Bolt spell has a 10% increased chance to trigger Missile Barrage, gains 10% increased critical strike chance while your Combustion spell is active, and has a 10% increased chance to trigger Fingers of Frost."] = "你的霜火箭法術觸發飛彈彈幕的機率提高10%，在燃灼法術生效期間，致命一擊機率提高10%，且觸發冰霜之指的機率提高10%。",
  ["Your Greater Heals now have a heal over time component equivalent to a rank 5 Renew."] = "當你施放強效治療術的時候，你也會自動免費施放恢復術（等級 5）。",
  ["Your Healing Wave and Lesser Healing Wave spells have a chance to imbue your target with Totemic Power. (Proc chance: 10%)"] = "你的治療波和次級治療波有一定機率使目標獲得圖騰之力。（觸發機率：10%）",
  ["Your Healing Wave will now jump to additional nearby targets. Each jump reduces the effectiveness of the heal by 80%, and the spell will jump to up to two additional targets."] = "你的治療波會治療一個額外的目標。治療波每次跳躍後的治療效果都會降低80%，並治療最多2個額外的目標。",
  ["Your Life Tap generates 20% more Mana at no additional Health cost."] = "你生命分流產生的法力提高20%，且不額外消耗生命力。",
  ["Your Lightning Bolt, Chain Lightning, and Shock spells have a 20% chance to grant up to 50 Nature damage to spells for 8 sec. (Proc chance: 20%)"] = "你的閃電箭、閃電鍊和震擊法術有20%的機率使法術的自然傷害提高最多50點，持續8秒。（觸發機率：20%）",
  ["Your Lightning Shield spell also grants you 15 mana per 5 sec. while active."] = "當閃電之盾啟動時可獲得每5秒恢復15點法力的效果。",
  ["Your Rejuvenation ticks have a chance to restore 60 mana, 8 energy, or 2 rage to your target."] = "你的回春術有機會在恢復目標生命時同時幫你的目標恢復60點法力、8點能量、或2點怒氣。",
  ["Your Shadow Bolts now have a chance to heal you for 270 to 330."] = "你的暗影箭現在有一定機率為你恢復270到330點生命力。",
  ["Your action bars and the spellbook."] = "你的快捷列和法術書。",
  ["Your attacks have a chance to increase your Attack Power by 40 and your healing spells have a chance to increase your Intellect by 20 for 15 sec. (Proc chance: 10%)"] = "你的攻擊有一定機率使攻擊強度提高40點，你的治療法術有一定機率使智力提高20點，持續15秒。（觸發機率：10%）",
  ["Your class"] = "你的職業",
  ["Your damage spells have a chance to cause your target to take up to 200 increased damage from subsequent spells. (Proc chance: 20%)"] = "你的傷害法術有一定機率使目標受到後續法術的傷害提高最多200點。（觸發機率：20%）",
  ["Your damage spells have a chance to displace you, causing the next spell cast to generate no threat. (Proc chance: 15%)"] = "你的傷害法術有一定機率使你產生位移，讓下一個施放的法術不產生威脅值。（觸發機率：15%）",
  ["Your elements stay as they are."] = "你的項目不會變。",
  ["Your faction and neutral ones. Click an entrance to open that dungeon in OneForAll. Zeppelins, ships, the tram and flight masters show where they go."] = "你的陣營和中立的。點入口可在 OneForAll 中打開那個地城。飛艇、船、地鐵和飛行管理員會顯示目的地。",
  ["Your finishing moves now refund 30 energy on a Miss, Dodge, Block, or Parry."] = "如果你的終結技未擊中目標、被閃躲、被格擋或被招架，則你可以回復30點能量值。",
  ["Your initial cast and Regrowth ticks will increase the maximum health of your target by up to 50, stacking up to 7 times."] = "每一次癒合的恢復效果產生時，提升目標的生命力上限最多50點 ，最多堆疊7次。",
  ["Your melee and ranged autoattacks have a 5% chance to energize you for 200 mana. (Proc chance: 5%)"] = "你的近戰和遠程自動攻擊有5%的機率為你恢復200點法力。（觸發機率：5%）",
  ["Your normal melee swings have a chance to Invigorate you, healing you for 90 to 110."] = "你的普通近戰攻擊有一定機率使你精力充沛，恢復90到110點生命力。",
  ["Your normal ranged attacks have a 4% chance of restoring 200 mana. (Proc chance: 4%)"] = "你的普通遠程攻擊有4%的機率恢復200點法力。（觸發機率：4%）",
  ["Your own custom weights stay as they are."] = "你自訂的權重不會變。",
  ["Your pet"] = "你的寵物",
  ["Your pet gains 15 stamina and 100 spell resistance against all schools of magic."] = "你的寵物獲得15點額外生命力，對所有魔法的抗性提高100點。",
  ["Your pet gains 20 stamina and 130 spell resistance against all schools of magic."] = "你的寵物獲得20點額外生命力，對所有魔法的抗性提高130點。",
  ["Your pet:"] = "你的寵物：",
  ["Your professions"] = "你的專業技能",
  ["Your progress and where the next quest starts"] = "你的進度以及下一個任務從哪裡開始",
  ["Your quiver or ammo pouch shows all arrows / bullets in your bags."] = "你的箭袋或彈藥袋顯示背包裡全部的箭／子彈。",
  ["Your ranged critical hits cause an Adrenaline Rush, granting you 50 mana."] = "你的遠程攻擊造成致命一擊後獲得能量刺激效果，回復50點法力。",
  ["Your skill:"] = "你的技能：",
  ["Your spell critical hits generate 25% less threat.  In addition, Corruption, Immolate, Curse of Agony, and Siphon Life generate 25% less threat."] = "你的法術造成致命一擊後降低該法術25%的威脅值。另外，腐蝕術，獻祭，痛苦詛咒和生命吸取所產生的威脅值降低25%。",
  ["Your spellcasts have a 5% chance to energize you for 200 mana. (Proc chance: 5%)"] = "你施法時有5%的機率恢復200點法力。（觸發機率：5%）",
  ["Your spellcasts have a 5% chance to heal you for 270 to 330. (Proc chance: 5%)"] = "你施法時有5%的機率為你恢復270到330點生命力。（觸發機率：5%）",
  ["Your standing:"] = "你的聲望：",
  ["Your tallstrider kicks up an abrasive cloud of dust, reducing the target's Armor by 175 for 30 sec."] = "你的陸行鳥揚起一陣粗糙的沙塵，使目標的護甲值降低175點，持續30秒。",
  ["Your tallstrider kicks up an abrasive cloud of dust, reducing the target's Armor by 285 for 30 sec."] = "你的陸行鳥揚起一陣粗糙的沙塵，使目標的護甲值降低285點，持續30秒。",
